    INSERT INTO "Question" ("id", "assessmentId", "textEn", "textFr", "order", "points", "setNumber") VALUES
      ('4e7545b1-3ac5-4e0a-a50a-ad17d43b6acf', a_id, $bp$What does the Preface say Jesus came to do, instead of starting a religion?$bp$, $bp$Selon la Préface, qu'est-ce que Jésus est venu faire, au lieu de fonder une religion ?$bp$, 0, 1, 1),
      ('4a3921c8-890b-4ff4-a3fd-15a9e53a23dd', a_id, $bp$According to the Introduction, what is the root cause of every problem humanity faces?$bp$, $bp$Selon l'Introduction, quelle est la cause profonde de tous les problèmes de l'humanité ?$bp$, 1, 1, 1),
      ('9a2391cf-f747-40ee-8281-a1ffc6092158', a_id, $bp$Why does the book say man is not merely the most advanced animal?$bp$, $bp$Pourquoi le livre dit-il que l'homme n'est pas simplement l'animal le plus évolué ?$bp$, 2, 1, 1),
      ('8f255fd6-1082-4973-adcc-970c05997eff', a_id, $bp$What does the book say the Garden of Eden was?$bp$, $bp$Selon le livre, qu'était le jardin d'Éden ?$bp$, 3, 1, 1),
      ('11afc94b-3607-42bd-bea8-a8fb5977cadd', a_id, $bp$What does the book say about the dominion mandate God gave in Genesis 1:26-28?$bp$, $bp$Que dit le livre du mandat de domination donné par Dieu en Genèse 1.26-28 ?$bp$, 4, 1, 1),
      ('42e5603a-8651-4073-9e89-42f1c65df81b', a_id, $bp$According to the book, why did God place one boundary (the forbidden tree) in the garden?$bp$, $bp$Selon le livre, pourquoi Dieu a-t-il placé une seule limite (l'arbre défendu) dans le jardin ?$bp$, 5, 1, 1),
      ('5317759a-74f0-4d99-a8b4-870c3d94e47f', a_id, $bp$According to the book, what was the enemy's first move in the garden?$bp$, $bp$Selon le livre, quel a été le premier coup de l'ennemi dans le jardin ?$bp$, 6, 1, 1),
      ('4435bbe9-22c8-4461-8dc7-735cfae25d7a', a_id, $bp$What does the book teach about the fear that entered after the fall?$bp$, $bp$Qu'enseigne le livre au sujet de la peur entrée après la chute ?$bp$, 7, 1, 1),
      ('260ce38b-993d-4fe5-8828-bd1bb24ef7cc', a_id, $bp$The book says every kingdom has four essential parts. Which list is correct?$bp$, $bp$Le livre dit que tout royaume a quatre éléments essentiels. Quelle liste est correcte ?$bp$, 8, 1, 1),
      ('08747c59-6f8d-444e-adbe-c841f4f44488', a_id, $bp$What does Jesus' prayer "Thy will be done in earth, as it is in Heaven" teach, according to the book?$bp$, $bp$Que nous enseigne la prière de Jésus « Que ta volonté soit faite sur la terre comme au ciel », selon le livre ?$bp$, 9, 1, 1),
      ('865919be-b14c-4b80-9bac-e3cd9b92693b', a_id, $bp$What lesson does the book draw from Elisha and his servant at Dothan?$bp$, $bp$Quelle leçon le livre tire-t-il d'Élisée et de son serviteur à Dothan ?$bp$, 10, 1, 1),
      ('2f721b53-1ae1-4ad5-83be-444b3a6da2a7', a_id, $bp$How does the book explain the difference between the Kingdom of Heaven and the Kingdom of God?$bp$, $bp$Comment le livre explique-t-il la différence entre le Royaume des Cieux et le Royaume de Dieu ?$bp$, 11, 1, 1),
      ('79f74b0a-849c-416c-b83a-26531fe68986', a_id, $bp$Which of these is NOT given in the book as a feature of an ambassador?$bp$, $bp$Laquelle de ces caractéristiques n'est PAS donnée dans le livre pour un ambassadeur ?$bp$, 12, 1, 1),
      ('742985b8-9b6a-4ee3-93a6-3f41adedd16b', a_id, $bp$What does the book say Peter's shadow healing the sick shows?$bp$, $bp$Que montre, selon le livre, l'ombre de Pierre qui guérissait les malades ?$bp$, 13, 1, 1),
      ('7770fea4-b076-4c74-9d01-df121230a74b', a_id, $bp$According to the book, how does the Kingdom behave in dark places, like the prison of Paul and Silas?$bp$, $bp$Selon le livre, comment le Royaume se comporte-t-il dans les lieux sombres, comme la prison de Paul et Silas ?$bp$, 14, 1, 1),
      ('56cd8596-77b4-4b4a-bae7-1512fe5a7284', a_id, $bp$What does the book say the word "repent" means?$bp$, $bp$Que signifie le mot « se repentir » selon le livre ?$bp$, 15, 1, 1),
      ('ddbf448a-e7f2-44af-a362-472cd9d48818', a_id, $bp$What does the book say about receiving Christ and entering the Kingdom?$bp$, $bp$Que dit le livre au sujet de recevoir Christ et d'entrer dans le Royaume ?$bp$, 16, 1, 1),
      ('aba99fc2-0064-4705-9f80-3695cd556d8b', a_id, $bp$Why does the book say "the violent take it by force" is not about physical aggression?$bp$, $bp$Pourquoi le livre dit-il que « les violents l'emportent » ne parle pas d'agressivité physique ?$bp$, 17, 1, 1),
      ('433ede18-528d-478f-b3c5-e22c96b5ae2c', a_id, $bp$What does the book say about Ephesians 2:6, "hath made us sit together in heavenly places"?$bp$, $bp$Que dit le livre d'Éphésiens 2.6, « nous a fait asseoir ensemble dans les lieux célestes » ?$bp$, 18, 1, 1),
      ('dd2868fb-27a6-4c09-807b-34ee49ce5dfc', a_id, $bp$What does the book say Joseph's story proves?$bp$, $bp$Que prouve l'histoire de Joseph, selon le livre ?$bp$, 19, 1, 1),
      ('9dfe5fe0-1211-41ed-a224-90865f2055ac', a_id, $bp$The book teaches that every great achievement in human history is a faint echo of the image of God still present in man.$bp$, $bp$Le livre enseigne que chaque grande réalisation de l'histoire humaine est un faible écho de l'image de Dieu encore présente dans l'homme.$bp$, 20, 1, 1),
      ('0e47288b-8cea-4a58-8543-dc5a6d1ae698', a_id, $bp$The book teaches that Adam and Eve dropped dead physically on the day they ate the fruit.$bp$, $bp$Le livre enseigne qu'Adam et Ève sont tombés morts physiquement le jour où ils ont mangé du fruit.$bp$, 21, 1, 1),
      ('79bd941e-105a-4665-af97-b5657ef69663', a_id, $bp$The book teaches that the Kingdom of Heaven is a denomination.$bp$, $bp$Le livre enseigne que le Royaume des Cieux est une dénomination.$bp$, 22, 1, 1),
      ('6be93178-b2eb-48ae-b562-b7724010b2a9', a_id, $bp$The book teaches that you will become God's dominion on earth only after you reach a high level of spiritual achievement.$bp$, $bp$Le livre enseigne que vous ne deviendrez la domination de Dieu sur la terre qu'après avoir atteint un haut niveau d'accomplissement spirituel.$bp$, 23, 1, 1),
      ('28a04298-f8ba-4413-8055-61bfad0d885f', a_id, $bp$The book teaches that the new birth is a ceremony that another person can perform on your behalf.$bp$, $bp$Le livre enseigne que la nouvelle naissance est une cérémonie qu'une autre personne peut accomplir à votre place.$bp$, 24, 1, 1);
    INSERT INTO "Option" ("id", "questionId", "textEn", "textFr", "isCorrect", "order") VALUES
      ('a36a69e2-bbaa-4fd2-af9a-fd770bf647f6', '4e7545b1-3ac5-4e0a-a50a-ad17d43b6acf', $bp$Save people from hell, and prepare them for the afterlife$bp$, $bp$Sauver les gens de l'enfer et les préparer à la vie après la mort$bp$, FALSE, 0),
      ('994f23e6-5ece-4635-867a-70686bd87908', '4e7545b1-3ac5-4e0a-a50a-ad17d43b6acf', $bp$Give people moral rules, and help them to live better lives$bp$, $bp$Donner aux gens des règles morales et les aider à mieux vivre$bp$, FALSE, 1),
      ('37a62dce-c40e-4112-be63-344b442c446a', '4e7545b1-3ac5-4e0a-a50a-ad17d43b6acf', $bp$Build a worldwide church, and bring people into its membership$bp$, $bp$Bâtir une Église mondiale et faire entrer les gens parmi ses membres$bp$, FALSE, 2),
      ('761f34be-fb4a-4a6e-84d0-40a0e92cb78e', '4e7545b1-3ac5-4e0a-a50a-ad17d43b6acf', $bp$Restore a Kingdom on earth, and restore man to his dominion$bp$, $bp$Rétablir un Royaume sur la terre et rétablir l'homme dans sa domination$bp$, TRUE, 3),
      ('329e91eb-0a46-48bc-858a-e6825432de4a', '4a3921c8-890b-4ff4-a3fd-15a9e53a23dd', $bp$Corrupt governments and failing political systems$bp$, $bp$Les gouvernements corrompus et les systèmes politiques défaillants$bp$, FALSE, 0),
      ('f1b1b8b4-124a-479d-b346-2536c83b5a69', '4a3921c8-890b-4ff4-a3fd-15a9e53a23dd', $bp$Poverty, lack of education, and weak economies$bp$, $bp$La pauvreté, le manque d'éducation et les économies fragiles$bp$, FALSE, 1),
      ('0a520f08-4b98-4b51-9620-be8fed217d9a', '4a3921c8-890b-4ff4-a3fd-15a9e53a23dd', $bp$Racial divisions and deep social inequality$bp$, $bp$Les divisions raciales et les profondes inégalités sociales$bp$, FALSE, 2),
      ('0878f810-57e0-4476-9261-ab79875ae414', '4a3921c8-890b-4ff4-a3fd-15a9e53a23dd', $bp$Spiritual disconnection from the Kingdom of God$bp$, $bp$La déconnexion spirituelle d'avec le Royaume de Dieu$bp$, TRUE, 3),
      ('57023ea1-01ba-44c5-b2e2-7c37688da3b4', '9a2391cf-f747-40ee-8281-a1ffc6092158', $bp$He was created last, which made him the most developed living creature$bp$, $bp$Il a été créé en dernier, ce qui fait de lui la créature vivante la plus développée$bp$, FALSE, 0),
      ('da01670d-6814-43fd-9f22-92c70f8d0c3f', '9a2391cf-f747-40ee-8281-a1ffc6092158', $bp$He alone was made in God's image and likeness, as a purposeful divine creation$bp$, $bp$Lui seul a été fait à l'image et à la ressemblance de Dieu, comme une création divine voulue$bp$, TRUE, 1),
      ('1d7e8e9e-d6cd-48e4-ad7c-aea54d8a26bf', '9a2391cf-f747-40ee-8281-a1ffc6092158', $bp$He alone was given a body, a mind, and the ability to speak and reason$bp$, $bp$Lui seul a reçu un corps, un esprit, et la capacité de parler et de raisonner$bp$, FALSE, 2),
      ('56a5c9a4-5c61-409f-82f4-c9a39f5a4060', '9a2391cf-f747-40ee-8281-a1ffc6092158', $bp$He has a larger brain and greater skill than any other creature$bp$, $bp$Il a un cerveau plus grand et plus d'habileté que toute autre créature$bp$, FALSE, 3),
      ('1a370805-9fce-408a-9691-ebcee3d927a7', '8f255fd6-1082-4973-adcc-970c05997eff', $bp$A Kingdom (dominion) headquarters where Heaven's rule was fully expressed$bp$, $bp$Un quartier général du Royaume (de la domination), où le règne du Ciel s'exprimait pleinement$bp$, TRUE, 0),
      ('bf58b60d-4bd5-4526-a78a-ca66bf0d50d7', '8f255fd6-1082-4973-adcc-970c05997eff', $bp$A school where God taught man the secrets of the angels$bp$, $bp$Une école où Dieu enseignait à l'homme les secrets des anges$bp$, FALSE, 1),
      ('319ad618-8622-4920-98fc-4be35dc12fd3', '8f255fd6-1082-4973-adcc-970c05997eff', $bp$A temple where man offered sacrifices to God every single day$bp$, $bp$Un temple où l'homme offrait des sacrifices à Dieu chaque jour$bp$, FALSE, 2),
      ('5dd1c7ad-047c-42cd-a0e3-4c1183528a30', '8f255fd6-1082-4973-adcc-970c05997eff', $bp$A beautiful park where man rested from governing the whole earth$bp$, $bp$Un beau parc où l'homme se reposait de gouverner toute la terre$bp$, FALSE, 3),
      ('42e45733-458a-4e6b-8726-4691200e1789', '11afc94b-3607-42bd-bea8-a8fb5977cadd', $bp$It was cancelled at the fall, since man had failed to obey Him$bp$, $bp$Il a été annulé à la chute, puisque l'homme n'avait pas obéi$bp$, FALSE, 0),
      ('70addcda-009a-4bb0-86dd-ae605d002750', '11afc94b-3607-42bd-bea8-a8fb5977cadd', $bp$It was given to Adam alone, and not passed on to his children$bp$, $bp$Il a été donné à Adam seul, et non transmis à ses enfants$bp$, FALSE, 1),
      ('2870938a-6ac3-4132-9114-27394af52ad4', '11afc94b-3607-42bd-bea8-a8fb5977cadd', $bp$It has never been revoked, because God has not changed His mind about man$bp$, $bp$Il n'a jamais été révoqué, car Dieu n'a pas changé d'avis au sujet de l'homme$bp$, TRUE, 2),
      ('2a12648e-3e83-45ad-a635-f788de0ce38c', '11afc94b-3607-42bd-bea8-a8fb5977cadd', $bp$It ended at the flood, when God started over with Noah's family$bp$, $bp$Il a pris fin au déluge, quand Dieu a recommencé avec la famille de Noé$bp$, FALSE, 3),
      ('e2d0d610-8552-44e3-aa9f-1d8db9091951', '42e5603a-8651-4073-9e89-42f1c65df81b', $bp$To protect man from something deadly, not to withhold something good$bp$, $bp$Pour protéger l'homme d'une chose mortelle, et non pour lui refuser une chose bonne$bp$, TRUE, 0),
      ('68fde769-757d-4c8e-a271-06afb6b7f16f', '42e5603a-8651-4073-9e89-42f1c65df81b', $bp$To test whether man was clever enough to avoid every temptation$bp$, $bp$Pour voir si l'homme était assez malin pour éviter toute tentation$bp$, FALSE, 1),
      ('d44bf8ce-ed04-458c-8008-01f283e59e07', '42e5603a-8651-4073-9e89-42f1c65df81b', $bp$To give the enemy a legal way to enter the garden and test him$bp$, $bp$Pour donner à l'ennemi un moyen légal d'entrer dans le jardin et de le tester$bp$, FALSE, 2),
      ('2acb98b1-6eb3-424f-9670-7c284f2a14fb', '42e5603a-8651-4073-9e89-42f1c65df81b', $bp$To keep man dependent on God and unable to become great$bp$, $bp$Pour garder l'homme dépendant de Dieu et l'empêcher de devenir grand$bp$, FALSE, 3),
      ('88591680-3953-416d-92de-e5369c22feaf', '5317759a-74f0-4d99-a8b4-870c3d94e47f', $bp$An open attack on Adam, to force him out of the garden$bp$, $bp$Une attaque ouverte contre Adam, pour le chasser du jardin$bp$, FALSE, 0),
      ('f7e0a05e-adcd-4a93-98ba-17971890852d', '5317759a-74f0-4d99-a8b4-870c3d94e47f', $bp$A miracle that impressed Eve and won her trust and loyalty$bp$, $bp$Un miracle qui a impressionné Ève et gagné sa confiance et sa loyauté$bp$, FALSE, 1),
      ('9681ada6-672b-43ff-b369-7d188b84c17f', '5317759a-74f0-4d99-a8b4-870c3d94e47f', $bp$A subtle question that planted doubt: "Hath God said?"$bp$, $bp$Une question subtile qui a semé le doute : « Dieu a-t-il réellement dit ? »$bp$, TRUE, 2),
      ('e0299792-110f-4434-b165-ea9fa12a3351', '5317759a-74f0-4d99-a8b4-870c3d94e47f', $bp$A direct threat that frightened Eve into obeying his plan$bp$, $bp$Une menace directe qui a effrayé Ève et l'a poussée à suivre son plan$bp$, FALSE, 3),
      ('3bd1256f-ae3c-421d-a8b9-6aa67e7d8220', '4435bbe9-22c8-4461-8dc7-735cfae25d7a', $bp$It is a natural part of human nature, and was in man from the day he was created$bp$, $bp$Elle fait naturellement partie de la nature humaine, et elle était en l'homme dès le jour de sa création$bp$, FALSE, 0),
      ('eae85011-1158-47eb-8f3d-40d5d2f28792', '4435bbe9-22c8-4461-8dc7-735cfae25d7a', $bp$It was given by God as a protection, to warn man of danger and keep him safe$bp$, $bp$Elle a été donnée par Dieu comme une protection, pour avertir l'homme du danger et le garder en sécurité$bp$, FALSE, 1),
      ('bba5037b-ab2a-48e9-8ec1-d98141335fd0', '4435bbe9-22c8-4461-8dc7-735cfae25d7a', $bp$It is the opposite of faith, and it rushed in when the connection with God was cut$bp$, $bp$Elle est le contraire de la foi, et elle s'est précipitée quand le lien avec Dieu a été coupé$bp$, TRUE, 2),
      ('7c93b7bb-fdb8-4ca2-a319-e9ca140992fc', '4435bbe9-22c8-4461-8dc7-735cfae25d7a', $bp$It came from the animals, which turned wild when man lost his authority over them$bp$, $bp$Elle est venue des animaux, devenus sauvages quand l'homme a perdu son autorité sur eux$bp$, FALSE, 3),
      ('adb719b8-d9ad-4cad-9a51-bcf01f9fda63', '260ce38b-993d-4fe5-8828-bd1bb24ef7cc', $bp$A king, a palace, servants, and wealth$bp$, $bp$Un roi, un palais, des serviteurs et des richesses$bp$, FALSE, 0),
      ('e4467675-3900-494f-9039-bbf5c8c88eeb', '260ce38b-993d-4fe5-8828-bd1bb24ef7cc', $bp$A king, an army, a treasury, and a law$bp$, $bp$Un roi, une armée, un trésor et une loi$bp$, FALSE, 1),
      ('4340e71d-3552-4927-9f6e-fadcc197e553', '260ce38b-993d-4fe5-8828-bd1bb24ef7cc', $bp$A king, a territory, a people, and a law$bp$, $bp$Un roi, un territoire, un peuple et une loi$bp$, TRUE, 2),
      ('042ff450-221d-4ad4-a7bc-ec00acdf86f8', '260ce38b-993d-4fe5-8828-bd1bb24ef7cc', $bp$A king, a temple, priests, and a law$bp$, $bp$Un roi, un temple, des prêtres et une loi$bp$, FALSE, 3),
      ('335e1703-0b8f-4d5e-aea8-99b67e1e43ca', '08747c59-6f8d-444e-adbe-c841f4f44488', $bp$Earth is a temporary place, so believers should focus only on Heaven and ignore earthly problems$bp$, $bp$La terre est un lieu provisoire, donc les croyants doivent se concentrer uniquement sur le Ciel et ignorer les problèmes terrestres$bp$, FALSE, 0),
      ('04aecdae-c5a0-4b0d-852a-5cee4d426cb4', '08747c59-6f8d-444e-adbe-c841f4f44488', $bp$Heaven is the template: what does not exist in Heaven, like poverty and sickness, is not God's design for earth$bp$, $bp$Le Ciel est le modèle : ce qui n'existe pas au Ciel, comme la pauvreté et la maladie, n'est pas le plan de Dieu pour la terre$bp$, TRUE, 1),
      ('662b5b5d-d9ed-482b-a669-a8eed71c0516', '08747c59-6f8d-444e-adbe-c841f4f44488', $bp$Heaven and earth are in constant conflict, and earth will always be ruled by the opposite of Heaven$bp$, $bp$Le Ciel et la terre sont en conflit permanent, et la terre sera toujours gouvernée par le contraire du Ciel$bp$, FALSE, 2),
      ('cc255e4c-aeb1-401a-ace4-137cf19b3cbb', '08747c59-6f8d-444e-adbe-c841f4f44488', $bp$Heaven's rules apply only after death, so earthly poverty and sickness are simply to be accepted$bp$, $bp$Les règles du Ciel ne s'appliquent qu'après la mort, donc la pauvreté et la maladie sur la terre sont simplement à accepter$bp$, FALSE, 3),
      ('6b73dc96-c0e3-49bb-9520-7af6f3c38edf', '865919be-b14c-4b80-9bac-e3cd9b92693b', $bp$Prayer removes every enemy army, so believers never face real opposition again$bp$, $bp$La prière supprime toute armée ennemie, donc les croyants ne rencontrent plus jamais de vraie opposition$bp$, FALSE, 0),
      ('b1603e3e-3f03-4255-bb61-bb0dd1075677', '865919be-b14c-4b80-9bac-e3cd9b92693b', $bp$The Kingdom is far away, and believers must pray hard to bring Heaven's armies near$bp$, $bp$Le Royaume est lointain, et les croyants doivent beaucoup prier pour rapprocher les armées du Ciel$bp$, FALSE, 1),
      ('02007d2b-b3fe-4ab6-b34a-2e9685b0622a', '865919be-b14c-4b80-9bac-e3cd9b92693b', $bp$The Kingdom is ever-present, and the armies of Heaven outnumber every opposition$bp$, $bp$Le Royaume est toujours présent, et les armées du Ciel sont plus nombreuses que toute opposition$bp$, TRUE, 2),
      ('3639967f-57d2-4815-bdbc-e72a5ecef017', '865919be-b14c-4b80-9bac-e3cd9b92693b', $bp$Servants should never look at the enemy, because seeing the danger breaks faith$bp$, $bp$Les serviteurs ne doivent jamais regarder l'ennemi, car voir le danger détruit la foi$bp$, FALSE, 3),
      ('776d2f2a-f8f9-4e14-b4ad-533009ffa852', '2f721b53-1ae1-4ad5-83be-444b3a6da2a7', $bp$They are two different kingdoms, one belonging to God and one belonging to the angels$bp$, $bp$Ce sont deux royaumes différents, l'un appartenant à Dieu et l'autre appartenant aux anges$bp$, FALSE, 0),
      ('d5caff3e-fd01-4e6e-97dc-a244b3263991', '2f721b53-1ae1-4ad5-83be-444b3a6da2a7', $bp$The Kingdom of God is for the Jews, and the Kingdom of Heaven is for the Gentiles$bp$, $bp$Le Royaume de Dieu est pour les Juifs, et le Royaume des Cieux est pour les non-Juifs$bp$, FALSE, 1),
      ('2a0bb696-a583-4f5b-b64c-60ba0482f9ee', '2f721b53-1ae1-4ad5-83be-444b3a6da2a7', $bp$Heaven is the source; the Kingdom of God is its authority expressed on earth through believers$bp$, $bp$Le Ciel est la source ; le Royaume de Dieu est son autorité exprimée sur la terre par les croyants$bp$, TRUE, 2),
      ('ed628f19-e51a-4fad-b8c7-4ef10bcd2d3c', '2f721b53-1ae1-4ad5-83be-444b3a6da2a7', $bp$The Kingdom of God is the heavenly realm; the Kingdom of Heaven is the church on earth$bp$, $bp$Le Royaume de Dieu est le domaine céleste ; le Royaume des Cieux est l'Église sur la terre$bp$, FALSE, 3),
      ('8f1e4c9e-97ab-4453-8d0b-eefe9a7d4ceb', '79f74b0a-849c-416c-b83a-26531fe68986', $bp$He is elected by the people of the foreign country$bp$, $bp$Il est élu par le peuple du pays étranger$bp$, TRUE, 0),
      ('25aa40c4-fef0-4727-923a-e2fbe4a31913', '79f74b0a-849c-416c-b83a-26531fe68986', $bp$He is appointed by the head of the sending nation$bp$, $bp$Il est nommé par le chef de la nation qui l'envoie$bp$, FALSE, 1),
      ('954c76fc-a40e-41c7-a175-2d1e7b85ae63', '79f74b0a-849c-416c-b83a-26531fe68986', $bp$He is provided for by the nation that sent him$bp$, $bp$Il est pris en charge par la nation qui l'a envoyé$bp$, FALSE, 2),
      ('9a5083c3-408d-4812-b677-087865ce55b2', '79f74b0a-849c-416c-b83a-26531fe68986', $bp$He carries the full authority of the nation he represents$bp$, $bp$Il porte toute l'autorité de la nation qu'il représente$bp$, FALSE, 3),
      ('ed494389-a415-42f0-a599-ff363e4978a6', '742985b8-9b6a-4ee3-93a6-3f41adedd16b', $bp$The Kingdom was so strongly expressed through him that it overflowed even through his shadow$bp$, $bp$Le Royaume s'exprimait si fortement à travers lui qu'il débordait même par son ombre$bp$, TRUE, 0),
      ('f694e987-650e-4ac8-a1ce-d079482a9f16', '742985b8-9b6a-4ee3-93a6-3f41adedd16b', $bp$Healing only works when the sick are brought into the street where the apostles pass by$bp$, $bp$La guérison ne fonctionne que si les malades sont amenés dans la rue où passent les apôtres$bp$, FALSE, 1),
      ('fa4202d4-78eb-42c4-bf7c-42a18376e3de', '742985b8-9b6a-4ee3-93a6-3f41adedd16b', $bp$Shadows carry a healing power, so the sick should always seek out a believer's shadow$bp$, $bp$Les ombres portent un pouvoir de guérison, donc les malades doivent toujours chercher l'ombre d'un croyant$bp$, FALSE, 2),
      ('90ea37cd-83fb-49d7-a348-a1686dedbcea', '742985b8-9b6a-4ee3-93a6-3f41adedd16b', $bp$Peter had special healing powers of his own, which were greater than those of the other apostles$bp$, $bp$Pierre avait ses propres pouvoirs de guérison, plus grands que ceux des autres apôtres$bp$, FALSE, 3),
      ('56c2baf7-bb61-476a-b2af-7b9a353ece38', '7770fea4-b076-4c74-9d01-df121230a74b', $bp$It avoids opposition, and works only where the environment is already friendly$bp$, $bp$Il évite l'opposition et n'agit que là où l'environnement est déjà favorable$bp$, FALSE, 0),
      ('a7ee1361-5ed9-4126-9ea5-894ede59c0b4', '7770fea4-b076-4c74-9d01-df121230a74b', $bp$It waits quietly in the darkness until the environment changes in its favour$bp$, $bp$Il attend en silence dans l'obscurité que l'environnement change en sa faveur$bp$, FALSE, 1),
      ('8d2d8051-db3d-49a9-8870-d03b5f842b31', '7770fea4-b076-4c74-9d01-df121230a74b', $bp$It does not wait for the environment to change; it changes the environment$bp$, $bp$Il n'attend pas que l'environnement change ; il change l'environnement$bp$, TRUE, 2),
      ('d87eaca8-51e8-4f42-ad23-2f30a6bef619', '7770fea4-b076-4c74-9d01-df121230a74b', $bp$It needs favourable conditions first, and then it begins to change things$bp$, $bp$Il a d'abord besoin de conditions favorables, puis il commence à changer les choses$bp$, FALSE, 3),
      ('de67d752-38de-4db7-a8d6-bb3bf7740692', '56cd8596-77b4-4b4a-bae7-1512fe5a7284', $bp$A deep feeling of sorrow that results in a promise to do better$bp$, $bp$Un profond sentiment de tristesse qui aboutit à la promesse de faire mieux$bp$, FALSE, 0),
      ('ebe2aca4-e039-4a5c-a305-2529a5739203', '56cd8596-77b4-4b4a-bae7-1512fe5a7284', $bp$A period of self-punishment that results in forgiveness from God$bp$, $bp$Une période d'autopunition qui aboutit au pardon de Dieu$bp$, FALSE, 1),
      ('37f88123-b3e3-4c9b-b120-7933fb7c520e', '56cd8596-77b4-4b4a-bae7-1512fe5a7284', $bp$A decision to join a church that results in a new religious life$bp$, $bp$La décision de rejoindre une Église qui aboutit à une nouvelle vie religieuse$bp$, FALSE, 2),
      ('fec4c837-c95c-430e-9861-972a65261342', '56cd8596-77b4-4b4a-bae7-1512fe5a7284', $bp$A change of mind that results in a change of direction$bp$, $bp$Un changement d'esprit qui aboutit à un changement de direction$bp$, TRUE, 3),
      ('ea8d4005-1ecb-4bf7-9a35-5ad02e452e27', 'ddbf448a-e7f2-44af-a362-472cd9d48818', $bp$Entering the Kingdom is a reward you work toward after you have received Christ$bp$, $bp$Entrer dans le Royaume est une récompense à laquelle on travaille après avoir reçu Christ$bp$, FALSE, 0),
      ('d15494b1-2dd6-485e-add1-7e894e1b4f29', 'ddbf448a-e7f2-44af-a362-472cd9d48818', $bp$They are two steps: first you receive Christ, then years later you enter the Kingdom$bp$, $bp$Ce sont deux étapes : d'abord on reçoit Christ, puis des années plus tard on entre dans le Royaume$bp$, FALSE, 1),
      ('2d4e41b3-b91e-49c8-9b98-a3a2fa1d9820', 'ddbf448a-e7f2-44af-a362-472cd9d48818', $bp$Only leaders and ministers enter the Kingdom, while other believers wait outside it$bp$, $bp$Seuls les dirigeants et les ministres entrent dans le Royaume, pendant que les autres croyants attendent dehors$bp$, FALSE, 2),
      ('bad7eef3-8486-4e5f-a428-ad52fe969aa4', 'ddbf448a-e7f2-44af-a362-472cd9d48818', $bp$They are the same thing: the moment you receive Christ, you are already in$bp$, $bp$C'est la même chose : au moment où vous recevez Christ, vous y êtes déjà$bp$, TRUE, 3),
      ('735cbd35-57f3-4bc2-ab44-6b8e5d7b8d47', 'aba99fc2-0064-4705-9f80-3695cd556d8b', $bp$It describes a wholehearted, decisive pursuit that refuses to be talked out of it$bp$, $bp$Cela décrit une poursuite entière et résolue, qui refuse de se laisser dissuader$bp$, TRUE, 0),
      ('5630e1d5-0233-4e77-960c-3bef276de28b', 'aba99fc2-0064-4705-9f80-3695cd556d8b', $bp$It describes people who take the Kingdom away from others by force and pressure$bp$, $bp$Cela décrit des gens qui enlèvent le Royaume aux autres par la force et la pression$bp$, FALSE, 1),
      ('9ed33c45-80ba-47c6-bebb-af34e0603f96', 'aba99fc2-0064-4705-9f80-3695cd556d8b', $bp$It describes the persecution that the early church suffered from violent rulers$bp$, $bp$Cela décrit la persécution que l'Église primitive a subie de la part de dirigeants violents$bp$, FALSE, 2),
      ('ccdb2712-2799-4ae2-bdfd-dd6a4f8edb7c', 'aba99fc2-0064-4705-9f80-3695cd556d8b', $bp$It describes believers who must physically fight their enemies to defend the Kingdom$bp$, $bp$Cela décrit des croyants qui doivent combattre physiquement leurs ennemis pour défendre le Royaume$bp$, FALSE, 3),
      ('b7e43690-0135-42f1-8d23-6274351daa20', '433ede18-528d-478f-b3c5-e22c96b5ae2c', $bp$It is in the past tense: you are already seated, a position you already occupy$bp$, $bp$C'est au passé : vous êtes déjà assis, une position que vous occupez déjà$bp$, TRUE, 0),
      ('3c42b03e-4c23-4407-b11c-eafd0b45b683', '433ede18-528d-478f-b3c5-e22c96b5ae2c', $bp$It is a position you must earn slowly through decades of faithful service$bp$, $bp$C'est une position à gagner lentement par des décennies de service fidèle$bp$, FALSE, 1),
      ('d1b719b2-4f45-41f5-8330-a62df3f359f1', '433ede18-528d-478f-b3c5-e22c96b5ae2c', $bp$It describes a position given only to apostles and the leaders of the early church$bp$, $bp$C'est une position donnée seulement aux apôtres et aux dirigeants de l'Église primitive$bp$, FALSE, 2),
      ('087764ca-e81e-48d0-a870-ff940cce5bc1', '433ede18-528d-478f-b3c5-e22c96b5ae2c', $bp$It is a future promise that will only be fulfilled after you die and go to Heaven$bp$, $bp$C'est une promesse future qui ne s'accomplira qu'après votre mort, quand vous irez au Ciel$bp$, FALSE, 3),
      ('2fea80ad-cd88-4926-b6ba-388809e6ca90', 'dd2868fb-27a6-4c09-807b-34ee49ce5dfc', $bp$Everyone must pass through prison before God can raise them into a position of rule$bp$, $bp$Tout le monde doit passer par la prison avant que Dieu puisse l'élever à une position de gouvernement$bp$, FALSE, 0),
      ('35bb87ef-5a74-4f5d-bb11-e0e29efa7113', 'dd2868fb-27a6-4c09-807b-34ee49ce5dfc', $bp$Suffering is always a punishment from God, and it ends when the sin is confessed$bp$, $bp$La souffrance est toujours une punition de Dieu, et elle cesse quand le péché est confessé$bp$, FALSE, 1),
      ('994b0101-6c35-482d-b40f-5d406a9c23de', 'dd2868fb-27a6-4c09-807b-34ee49ce5dfc', $bp$No circumstance can permanently contain a person whose connection to the Kingdom stays intact$bp$, $bp$Aucune circonstance ne peut retenir définitivement une personne dont le lien avec le Royaume reste intact$bp$, TRUE, 2),
      ('f2d663ef-a319-48e2-b803-6141d0502f1b', 'dd2868fb-27a6-4c09-807b-34ee49ce5dfc', $bp$Family can never be trusted, so a believer should depend on no one but himself$bp$, $bp$On ne peut jamais faire confiance à sa famille, donc un croyant ne doit compter que sur lui-même$bp$, FALSE, 3),
      ('617132e9-ee03-4961-8d24-76771d2b9929', '9dfe5fe0-1211-41ed-a224-90865f2055ac', $bp$TRUE$bp$, $bp$VRAI$bp$, TRUE, 0),
      ('e9662fe3-0c01-48b3-94e4-c6a94ec8312c', '9dfe5fe0-1211-41ed-a224-90865f2055ac', $bp$FALSE$bp$, $bp$FAUX$bp$, FALSE, 1),
      ('c2ea3d53-c4f1-41f5-8b40-0d7c5312914e', '0e47288b-8cea-4a58-8543-dc5a6d1ae698', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('db5246f6-0e68-41d9-a695-f77b67b5a66b', '0e47288b-8cea-4a58-8543-dc5a6d1ae698', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1),
      ('39450454-223b-437b-91d6-99909dab2f9a', '79bd941e-105a-4665-af97-b5657ef69663', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('bf9a6941-14d9-4ff2-90a6-51bf373f6dac', '79bd941e-105a-4665-af97-b5657ef69663', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1),
      ('b1a2c5b4-25fe-45d7-8166-f01f6faf7301', '6be93178-b2eb-48ae-b562-b7724010b2a9', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('609ad820-a82d-4e68-81e1-51bf3d990526', '6be93178-b2eb-48ae-b562-b7724010b2a9', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1),
      ('ed08e074-7701-4e8e-87eb-f5df10f94d73', '28a04298-f8ba-4413-8055-61bfad0d885f', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('ff907eff-c9e0-4dbd-9722-3a1b6c4b862c', '28a04298-f8ba-4413-8055-61bfad0d885f', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1);
    INSERT INTO "PersonalQuestion" ("id", "assessmentId", "setNumber", "order", "kind", "textEn", "textFr", "bodyEn", "bodyFr", "guideEn", "guideFr", "required", "flagUnlessNone", "affectsStatus") VALUES
      ('019a2996-1813-4617-9e86-ac892460d411', a_id, 1, 0, 'CHOICE', $bp$Chapter Five says repentance is a change of mind that results in a change of direction: turning from your own way to God's way. Have you made that decision?$bp$, $bp$Le chapitre cinq dit que la repentance est un changement d'esprit qui aboutit à un changement de direction : se détourner de sa propre voie pour prendre celle de Dieu. Avez-vous pris cette décision ?$bp$, NULL, NULL, $bp$Yes: ask what changed in their life. Not yet, on the way, or not sure: explain repentance as a decision, not a feeling (Chapter Five, Matthew 21:28-29). Invite them to decide today.$bp$, $bp$Oui : demandez ce qui a changé dans sa vie. Pas encore, en chemin ou pas sûr : expliquez la repentance comme une décision, pas comme un sentiment (chapitre cinq, Matthieu 21.28-29). Invitez la personne à se décider aujourd'hui.$bp$, TRUE, FALSE, TRUE),
      ('aa03993b-9fe5-42ae-a112-d5225ea4c709', a_id, 1, 1, 'CHOICE', $bp$The book says saving belief is more than agreement. Do you believe in your heart that Jesus died for your sins and that God raised Him from the dead?$bp$, $bp$Le livre dit que la foi qui sauve est plus qu'un accord de l'esprit. Croyez-vous dans votre cœur que Jésus est mort pour vos péchés et que Dieu l'a ressuscité des morts ?$bp$, NULL, NULL, $bp$Doubts or no: do not argue. Walk through Romans 10:9 and John 3:16 with them, and let them ask their questions.$bp$, $bp$Doutes ou non : ne discutez pas. Parcourez avec elle Romains 10.9 et Jean 3.16, et laissez-la poser ses questions.$bp$, TRUE, FALSE, TRUE),
      ('de1a0778-89d4-49a1-8f06-10ad86b79764', a_id, 1, 2, 'CHOICE', $bp$Have you confessed Jesus with your mouth as your Lord and Saviour (Romans 10:9)?$bp$, $bp$Avez-vous confessé de votre bouche Jésus comme votre Seigneur et Sauveur (Romains 10.9) ?$bp$, NULL, NULL, $bp$If they have not confessed Him, offer to pray the prayer at the end of Chapter Five aloud with them.$bp$, $bp$Si elle ne l'a pas confessé, proposez de prier à voix haute avec elle la prière de la fin du chapitre cinq.$bp$, TRUE, FALSE, TRUE),
      ('e25fd552-7e73-46ec-ba5b-a6c6e9f0644e', a_id, 1, 3, 'TEXT', $bp$If yes, when did this happen? (a year, or a season of your life)$bp$, $bp$Si oui, quand cela s'est-il passé ? (une année, ou une période de votre vie)$bp$, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE),
      ('52e79d6f-3144-4fc9-8c0b-fcd6116565fb', a_id, 1, 4, 'CHOICE', $bp$Jesus said, "Except a man be born again, he cannot see the kingdom of God." Do you know that you have been born again?$bp$, $bp$Jésus a dit : « Si un homme ne naît de nouveau, il ne peut voir le royaume de Dieu. » Savez-vous que vous êtes né de nouveau ?$bp$, NULL, NULL, $bp$Unsure or no: explain John 3:3-5 and 1 Peter 1:23 (born again by receiving the Word). Pray the Chapter Five prayer with them.$bp$, $bp$Pas sûr ou non : expliquez Jean 3.3-5 et 1 Pierre 1.23 (né de nouveau en recevant la Parole). Priez avec elle la prière du chapitre cinq.$bp$, TRUE, FALSE, TRUE),
      ('333f0715-45a0-47a1-a1cd-60fb864e5877', a_id, 1, 5, 'TEXT', $bp$What is the one thing, if any, that is holding you back from giving your whole life to Jesus Christ? If nothing, write "nothing".$bp$, $bp$Quelle est la seule chose, s'il y en a une, qui vous retient de donner toute votre vie à Jésus-Christ ? S'il n'y a rien, écrivez « rien ».$bp$, NULL, NULL, $bp$Read this answer with great care and pray over it. Name the barrier gently, and remind them of the section "No One Is Disqualified" in Chapter Five.$bp$, $bp$Lisez cette réponse avec grande attention et priez à son sujet. Nommez doucement l'obstacle et rappelez-lui la section « Personne n'est disqualifié » du chapitre cinq.$bp$, TRUE, TRUE, TRUE),
      ('3f62dde2-486e-4eab-bc6f-5ff3f7c4ce28', a_id, 1, 6, 'CHOICE', $bp$My Confession of Faith$bp$, $bp$Ma confession de foi$bp$, $bp$Read this confession slowly, and think about every word. If it is the true desire of your heart, tick "I agree". If you are not ready, tick "I do not agree". You will not be judged for being honest.
    INSERT INTO "PersonalOption" ("id", "questionId", "order", "textEn", "textFr", "signal") VALUES
      ('b1359bb8-539d-4c4d-ad8f-60ee7d12431f', '019a2996-1813-4617-9e86-ac892460d411', 0, $bp$Yes, I have made that decision$bp$, $bp$Oui, j'ai pris cette décision$bp$, 'POSITIVE'),
      ('27aa54e6-9aa0-4494-870a-42aa81ade4b1', '019a2996-1813-4617-9e86-ac892460d411', 1, $bp$I am on the way, but I have not fully turned yet$bp$, $bp$Je suis en chemin, mais je ne me suis pas encore pleinement tourné$bp$, 'NEEDS_TALK'),
      ('ff3ca0cc-9381-4e26-8d34-3594af5a9aa3', '019a2996-1813-4617-9e86-ac892460d411', 2, $bp$Not yet$bp$, $bp$Pas encore$bp$, 'NEEDS_TALK'),
      ('6f3df883-5227-47c1-af5d-9bde9f203263', '019a2996-1813-4617-9e86-ac892460d411', 3, $bp$I am not sure what this means for me$bp$, $bp$Je ne suis pas sûr de ce que cela signifie pour moi$bp$, 'NEEDS_TALK'),
      ('be513a4d-49cd-46b9-8f2d-f4bf5225b1f4', 'aa03993b-9fe5-42ae-a112-d5225ea4c709', 0, $bp$Yes, I believe it fully$bp$, $bp$Oui, je le crois pleinement$bp$, 'POSITIVE'),
      ('9f1c7840-5f9e-4960-89ac-dfe5baa17e1f', 'aa03993b-9fe5-42ae-a112-d5225ea4c709', 1, $bp$I want to believe, but I still have doubts$bp$, $bp$Je veux le croire, mais j'ai encore des doutes$bp$, 'NEEDS_TALK'),
      ('c8502c42-0c27-4540-a1b7-1d5bb03af553', 'aa03993b-9fe5-42ae-a112-d5225ea4c709', 2, $bp$No, I do not believe it yet$bp$, $bp$Non, je ne le crois pas encore$bp$, 'NEEDS_TALK'),
      ('913b84c1-85dc-4c59-ab7d-3f511ca79fa0', 'aa03993b-9fe5-42ae-a112-d5225ea4c709', 3, $bp$I am not sure$bp$, $bp$Je ne suis pas sûr$bp$, 'NEEDS_TALK'),
      ('42ddf7d6-97b2-4187-a0f6-45229b480ef9', 'de1a0778-89d4-49a1-8f06-10ad86b79764', 0, $bp$Yes, I have$bp$, $bp$Oui, je l'ai fait$bp$, 'POSITIVE'),
      ('224a2139-41d7-4ed9-a3e7-6aceada5b177', 'de1a0778-89d4-49a1-8f06-10ad86b79764', 1, $bp$No, but I would like to do it now$bp$, $bp$Non, mais j'aimerais le faire maintenant$bp$, 'NEEDS_TALK'),
      ('de2a723b-2002-4ba5-aa88-84e43160f866', 'de1a0778-89d4-49a1-8f06-10ad86b79764', 2, $bp$Not yet$bp$, $bp$Pas encore$bp$, 'NEEDS_TALK'),
      ('d56b3570-b514-4e34-bdc4-07c3ec064409', '52e79d6f-3144-4fc9-8c0b-fcd6116565fb', 0, $bp$Yes, I know I am born again$bp$, $bp$Oui, je sais que je suis né de nouveau$bp$, 'POSITIVE'),
      ('0dd1c47d-9830-49a9-9f2c-4838c57e9cbb', '52e79d6f-3144-4fc9-8c0b-fcd6116565fb', 1, $bp$I think so, but I am not sure$bp$, $bp$Je le pense, mais je n'en suis pas sûr$bp$, 'NEEDS_TALK'),
      ('aeca51a4-cae0-4b6a-8f25-5c9178da39b2', '52e79d6f-3144-4fc9-8c0b-fcd6116565fb', 2, $bp$No, I am not born again$bp$, $bp$Non, je ne suis pas né de nouveau$bp$, 'NEEDS_TALK'),
      ('7dc569b1-3274-4e62-ad76-4ea5ab202507', '52e79d6f-3144-4fc9-8c0b-fcd6116565fb', 3, $bp$I do not understand what this means$bp$, $bp$Je ne comprends pas ce que cela veut dire$bp$, 'NEEDS_TALK'),
      ('2a8ef0f1-84b7-4043-9d36-5c9cc5c02994', '3f62dde2-486e-4eab-bc6f-5ff3f7c4ce28', 0, $bp$I agree with this confession, and I make it my own$bp$, $bp$Je suis d'accord avec cette confession, et je la fais mienne$bp$, 'POSITIVE'),
      ('83a42680-e2be-435c-97bd-7a8131227dab', '3f62dde2-486e-4eab-bc6f-5ff3f7c4ce28', 1, $bp$I do not agree with this confession$bp$, $bp$Je ne suis pas d'accord avec cette confession$bp$, 'NEEDS_TALK');
    INSERT INTO "Question" ("id", "assessmentId", "textEn", "textFr", "order", "points", "setNumber") VALUES
      ('5985cba0-808e-476e-b207-53948d31e8c8', a_id, $bp$What does the Preface say being born again really is?$bp$, $bp$Selon la Préface, qu'est-ce que la nouvelle naissance est vraiment ?$bp$, 0, 1, 2),
      ('58aa86c1-f338-4481-9983-a3dad01d6391', a_id, $bp$According to the Introduction, what are people who risk everything to emigrate to richer nations really searching for?$bp$, $bp$Selon l'Introduction, que cherchent vraiment les personnes qui risquent tout pour émigrer vers des nations plus riches ?$bp$, 1, 1, 2),
      ('da9fccd3-bf05-4578-a980-f68f37a883e8', a_id, $bp$What does the book say the words "Let us make man" show?$bp$, $bp$Que montrent, selon le livre, les mots « Faisons l'homme » ?$bp$, 2, 1, 2),
      ('09597f00-7bd3-4ac5-9a93-8d608413a2ee', a_id, $bp$In the book, what does the word "likeness" speak of?$bp$, $bp$Dans le livre, de quoi parle le mot « ressemblance » ?$bp$, 3, 1, 2),
      ('93542d14-cef2-4f42-a771-c8a44e26029b', a_id, $bp$What does the book say Adam's naming of the animals proves?$bp$, $bp$Que prouve, selon le livre, le fait qu'Adam ait donné des noms aux animaux ?$bp$, 4, 1, 2),
      ('49807a68-8357-49fb-8961-13d34ce595f7', a_id, $bp$According to Chapter Two, what exactly died on the day Adam ate the fruit?$bp$, $bp$Selon le chapitre deux, qu'est-ce qui est mort exactement le jour où Adam a mangé du fruit ?$bp$, 5, 1, 2),
      ('8958e9e6-1f83-4e63-a8df-97236442d1d2', a_id, $bp$The book links the three things that drew Eve to the tree with which three temptations of 1 John 2:16?$bp$, $bp$Le livre relie les trois choses qui ont attiré Ève vers l'arbre à quelles trois tentations de 1 Jean 2.16 ?$bp$, 6, 1, 2),
      ('842dc3f7-ab2d-4241-a2a1-fbbd3e36fdaa', a_id, $bp$How does the book explain the enemy gaining legal possession of the kingdoms of this world?$bp$, $bp$Comment le livre explique-t-il que l'ennemi ait obtenu légalement la possession des royaumes de ce monde ?$bp$, 7, 1, 2),
      ('0aab5d4d-571b-499e-a972-714b81231b73', a_id, $bp$How does the book describe the Kingdom of Heaven?$bp$, $bp$Comment le livre décrit-il le Royaume des Cieux ?$bp$, 8, 1, 2),
      ('dec89f49-5932-4e20-aeac-285e77c20d87', a_id, $bp$Which statement about the Kingdom of Heaven is true according to the book?$bp$, $bp$Quelle affirmation sur le Royaume des Cieux est vraie selon le livre ?$bp$, 9, 1, 2),
      ('1ed10c42-3caa-44bb-8084-1a5fbbc716a7', a_id, $bp$What detail about Jesus in Stephen's vision does the book highlight?$bp$, $bp$Quel détail sur Jésus, dans la vision d'Étienne, le livre souligne-t-il ?$bp$, 10, 1, 2),
      ('b6732624-5f21-4d39-8e4a-925385cb9363', a_id, $bp$What does the book say "the Kingdom of God is within you" means?$bp$, $bp$Que signifie, selon le livre, « le royaume de Dieu est au milieu de vous » ?$bp$, 11, 1, 2),
      ('8bd06284-47e6-4b47-8e26-36806c2d4ce5', a_id, $bp$According to the book, what does "the Kingdom of God is not in word, but in power" strip away?$bp$, $bp$Selon le livre, qu'est-ce que « le royaume de Dieu ne consiste pas en paroles, mais en puissance » met à nu ?$bp$, 12, 1, 2),
      ('828a5fd4-1d29-4d8d-9099-099053913881', a_id, $bp$What happened when Philip went to Samaria, according to the book?$bp$, $bp$Que s'est-il passé quand Philippe est allé en Samarie, selon le livre ?$bp$, 13, 1, 2),
      ('a0ae2341-8ae4-4dd2-85f5-9ec0f47e33e0', a_id, $bp$Why does the book say God placed the Kingdom's power in ordinary, earthen vessels?$bp$, $bp$Pourquoi le livre dit-il que Dieu a placé la puissance du Royaume dans des vases de terre ordinaires ?$bp$, 14, 1, 2),
      ('543904c1-ea4a-4b1f-948c-11450b89edc4', a_id, $bp$What does the book say Jesus preached above all other messages?$bp$, $bp$Que dit le livre que Jésus a prêché par-dessus tous les autres messages ?$bp$, 15, 1, 2),
      ('8abde7d6-15a7-49d5-aaf2-94f0f98a7d07', a_id, $bp$Why does the book say a "door" (the sacrifice of Christ) was needed at all?$bp$, $bp$Pourquoi le livre dit-il qu'une « porte » (le sacrifice de Christ) était nécessaire ?$bp$, 16, 1, 2),
      ('87a79505-ea6a-40b5-8dcb-5b8491affc05', a_id, $bp$What does the book say about the thief on the cross?$bp$, $bp$Que dit le livre du voleur sur la croix ?$bp$, 17, 1, 2),
      ('2d3e9405-8c2d-402c-a618-4fdd87450ac1', a_id, $bp$What does the Conclusion say about the dominion you receive in Christ?$bp$, $bp$Que dit la Conclusion de la domination que vous recevez en Christ ?$bp$, 18, 1, 2),
      ('e92fa7b1-92d9-490c-87ee-fe2185586a0a', a_id, $bp$What does the book say Esther's story means for you?$bp$, $bp$Que signifie pour vous l'histoire d'Esther, selon le livre ?$bp$, 19, 1, 2),
      ('ffdf1271-093d-4b77-8f43-0ba92eecd04f', a_id, $bp$The book says Solomon shows what a man looks like when he functions close to his original Kingdom design.$bp$, $bp$Le livre dit que Salomon montre à quoi ressemble un homme qui fonctionne près de son plan original du Royaume.$bp$, 20, 1, 2),
      ('f068c0a4-e796-455a-be40-570faffedd9d', a_id, $bp$The book says Samson's story ends with no hope of restoration.$bp$, $bp$Le livre dit que l'histoire de Samson se termine sans aucun espoir de restauration.$bp$, 21, 1, 2),
      ('6a2020ea-1b82-4b80-82aa-5f6086c108ef', a_id, $bp$The book teaches that death is the end of the story for a citizen of Heaven.$bp$, $bp$Le livre enseigne que la mort est la fin de l'histoire pour un citoyen du Ciel.$bp$, 22, 1, 2),
      ('28357ddc-ad45-4413-8985-219edadf89a9', a_id, $bp$The book teaches that the signs of Mark 16:17-18 follow every faith-walking believer, not only a gifted few.$bp$, $bp$Le livre enseigne que les signes de Marc 16.17-18 accompagnent chaque croyant qui marche par la foi, et pas seulement quelques personnes douées.$bp$, 23, 1, 2),
      ('ecd2a80e-ad3f-49d0-bf20-f0b8979c4a61', a_id, $bp$The book teaches that believing in Jesus only means agreeing that He lived and died on a cross.$bp$, $bp$Le livre enseigne que croire en Jésus signifie seulement admettre qu'il a vécu et qu'il est mort sur une croix.$bp$, 24, 1, 2);
    INSERT INTO "Option" ("id", "questionId", "textEn", "textFr", "isCorrect", "order") VALUES
      ('12128ee3-334d-4acc-9cff-fb36e828a841', '5985cba0-808e-476e-b207-53948d31e8c8', $bp$A reward given to believers who have served faithfully in a church for many years$bp$, $bp$Une récompense donnée aux croyants qui ont fidèlement servi dans une Église pendant de nombreuses années$bp$, FALSE, 0),
      ('f4a41ddb-eae4-4e88-9200-af6ced1aea0d', '5985cba0-808e-476e-b207-53948d31e8c8', $bp$A ceremony that joins a person to a church family, giving belonging and a ticket to Heaven$bp$, $bp$Une cérémonie qui rattache une personne à une famille d'Église, lui donnant un sentiment d'appartenance et un billet pour le Ciel$bp$, FALSE, 1),
      ('474df273-4f86-418d-a511-ea66b86bb0f3', '5985cba0-808e-476e-b207-53948d31e8c8', $bp$A transfer into the most powerful governing reality in existence, not merely a ticket to Heaven$bp$, $bp$Un transfert dans la réalité gouvernante la plus puissante qui existe, et pas seulement un billet pour le Ciel$bp$, TRUE, 2),
      ('a1f98b88-e446-40b9-942d-08749fb10290', '5985cba0-808e-476e-b207-53948d31e8c8', $bp$A promise to live a better life, which earns a person a place in Heaven after death$bp$, $bp$Une promesse de mieux vivre, qui vaut à la personne une place au Ciel après la mort$bp$, FALSE, 3),
      ('5dc603d0-e70b-4ff6-9769-52c15c246cda', '58aa86c1-f338-4481-9983-a3dad01d6391', $bp$A new religion: a spiritual system that finally gives them peace and meaning$bp$, $bp$Une nouvelle religion : un système spirituel qui leur donne enfin la paix et un sens$bp$, FALSE, 0),
      ('c2260b46-bb28-4716-af80-75a31ea14291', '58aa86c1-f338-4481-9983-a3dad01d6391', $bp$Escape: freedom from their families, their past, and every painful memory$bp$, $bp$Une évasion : la liberté de leur famille, de leur passé et de tous leurs souvenirs douloureux$bp$, FALSE, 1),
      ('b59ee3ed-c529-479c-87a6-4513871ac3c1', '58aa86c1-f338-4481-9983-a3dad01d6391', $bp$Dominion: the ability to govern their circumstances instead of being governed by them$bp$, $bp$La domination : la capacité de gouverner leurs circonstances au lieu d'être gouvernées par elles$bp$, TRUE, 2),
      ('9a5caf98-1df5-461f-b155-cc3e794b6b36', '58aa86c1-f338-4481-9983-a3dad01d6391', $bp$Wealth: a comfortable life with enough money to pay for every need and desire$bp$, $bp$La richesse : une vie confortable avec assez d'argent pour payer tous les besoins et tous les désirs$bp$, FALSE, 3),
      ('a4567f8c-f4e6-4a7a-b0db-0823d8b20195', 'da9fccd3-bf05-4578-a980-f68f37a883e8', $bp$A correction of an earlier mistake, as God decided to remake creatures He had already made$bp$, $bp$La correction d'une erreur antérieure, Dieu ayant décidé de refaire des créatures qu'il avait déjà faites$bp$, FALSE, 0),
      ('f1de5f21-cd5a-4db0-a3cc-657b4a36532f', 'da9fccd3-bf05-4578-a980-f68f37a883e8', $bp$A repeat of the same process used for the animals, simply applied again to the creation of man$bp$, $bp$La répétition du même procédé utilisé pour les animaux, simplement appliqué de nouveau à la création de l'homme$bp$, FALSE, 1),
      ('f9739ada-5c55-4e13-85e7-52be1ce4f3d7', 'da9fccd3-bf05-4578-a980-f68f37a883e8', $bp$A discussion with the angels, who helped God decide how man should be designed and made$bp$, $bp$Une discussion avec les anges, qui ont aidé Dieu à décider comment l'homme devait être conçu et fait$bp$, FALSE, 2),
      ('c6ebac28-e071-4cb2-bf70-b281a03ed1cc', 'da9fccd3-bf05-4578-a980-f68f37a883e8', $bp$A deliberate, considered act of divine craftsmanship, different from everything else God spoke into being$bp$, $bp$Un acte délibéré et réfléchi de création divine, différent de tout ce que Dieu a fait exister par sa parole$bp$, TRUE, 3),
      ('f8120f9c-12d9-412d-a918-4fb73e65d9c7', '09597f00-7bd3-4ac5-9a93-8d608413a2ee', $bp$Similarity of nature: man was made to think, create, and govern like God$bp$, $bp$D'une similitude de nature : l'homme a été fait pour penser, créer et gouverner comme Dieu$bp$, TRUE, 0),
      ('74623fe8-db43-42cb-bcfa-8ae962780591', '09597f00-7bd3-4ac5-9a93-8d608413a2ee', $bp$A religious symbol: man was made to carry a sign of worship on the earth$bp$, $bp$D'un symbole religieux : l'homme a été fait pour porter un signe d'adoration sur la terre$bp$, FALSE, 1),
      ('4128c686-6e01-4a40-bd4d-6576584bc0e3', '09597f00-7bd3-4ac5-9a93-8d608413a2ee', $bp$A royal title: man was made to be called a king by all the animals$bp$, $bp$D'un titre royal : l'homme a été fait pour être appelé roi par tous les animaux$bp$, FALSE, 2),
      ('9fa827fe-501a-4c40-bae4-61bfde9a9a68', '09597f00-7bd3-4ac5-9a93-8d608413a2ee', $bp$A physical resemblance: man was made to look like God in face and in body$bp$, $bp$D'une ressemblance physique : l'homme a été fait pour ressembler à Dieu par le visage et par le corps$bp$, FALSE, 3),
      ('582dea5c-91e3-43ea-81db-3427756302ce', '93542d14-cef2-4f42-a771-c8a44e26029b', $bp$Adam was gifted with words, and God was impressed by how clever his names were$bp$, $bp$Adam avait le don des mots, et Dieu a été impressionné par l'intelligence de ses noms$bp$, FALSE, 0),
      ('1b31b43c-3d7a-46a0-b495-f71d39a0eb70', '93542d14-cef2-4f42-a771-c8a44e26029b', $bp$God was testing Adam's memory, to see how many creatures he could remember$bp$, $bp$Dieu mettait à l'épreuve la mémoire d'Adam, pour voir combien de créatures il pouvait retenir$bp$, FALSE, 1),
      ('8738b054-f585-486a-927f-c186fd872e17', '93542d14-cef2-4f42-a771-c8a44e26029b', $bp$Adam held real governing authority, and God honoured whatever he decided$bp$, $bp$Adam détenait une vraie autorité de gouvernement, et Dieu honorait tout ce qu'il décidait$bp$, TRUE, 2),
      ('801f9a25-b9ee-4cbf-bb94-3fcb67ed9b82', '93542d14-cef2-4f42-a771-c8a44e26029b', $bp$Animals needed names before the fall, so that God could tell them apart in the garden$bp$, $bp$Les animaux avaient besoin de noms avant la chute, pour que Dieu puisse les distinguer dans le jardin$bp$, FALSE, 3),
      ('e4c4ec5a-252b-4731-8480-789be91656fb', '49807a68-8357-49fb-8961-13d34ce595f7', $bp$His body: it began to age and decay on the very day that he ate the fruit$bp$, $bp$Son corps : il a commencé à vieillir et à se dégrader le jour même où il a mangé du fruit$bp$, FALSE, 0),
      ('53669dc9-0e7f-4453-8823-b4a740f6143a', '49807a68-8357-49fb-8961-13d34ce595f7', $bp$His mind: he lost the ability to think clearly, to reason, and to make wise choices$bp$, $bp$Son intelligence : il a perdu la capacité de penser clairement, de raisonner et de faire de sages choix$bp$, FALSE, 1),
      ('a7ed401c-036c-45ba-a051-6e8ff9c3a950', '49807a68-8357-49fb-8961-13d34ce595f7', $bp$His spirit: his connection with God, which gave him identity, wisdom, and authority$bp$, $bp$Son esprit : son lien avec Dieu, qui lui donnait son identité, sa sagesse et son autorité$bp$, TRUE, 2),
      ('0125fa5f-b172-4766-9fee-48523f834646', '49807a68-8357-49fb-8961-13d34ce595f7', $bp$His soul: the part of him that felt joy, love, and happiness was destroyed for ever$bp$, $bp$Son âme : la partie de lui qui ressentait la joie, l'amour et le bonheur a été détruite pour toujours$bp$, FALSE, 3),
      ('be69bf69-7784-4606-a1d6-520e2ce77f54', '8958e9e6-1f83-4e63-a8df-97236442d1d2', $bp$The lust of the flesh, the lust of the eyes, and the pride of life$bp$, $bp$La convoitise de la chair, la convoitise des yeux et l'orgueil de la vie$bp$, TRUE, 0),
      ('6977ee51-df29-43bc-8c94-600389a8e5d6', '8958e9e6-1f83-4e63-a8df-97236442d1d2', $bp$Greed for riches, envy of others, and anger toward those in authority$bp$, $bp$L'avidité des richesses, l'envie des autres et la colère envers ceux qui ont l'autorité$bp$, FALSE, 1),
      ('8c6eda29-7d70-4ea3-baa4-60937329b429', '8958e9e6-1f83-4e63-a8df-97236442d1d2', $bp$Fear of death, doubt of God's word, and the unbelief of the heart$bp$, $bp$La peur de la mort, le doute de la parole de Dieu et l'incrédulité du cœur$bp$, FALSE, 2),
      ('ad9c6a3b-9c04-4c3a-959f-724b7ee85665', '8958e9e6-1f83-4e63-a8df-97236442d1d2', $bp$Pride of position, rebellion against rule, and the worship of other gods$bp$, $bp$L'orgueil de la position, la rébellion contre l'autorité et l'adoration d'autres dieux$bp$, FALSE, 3),
      ('8bca0da1-2707-4b62-885e-e27465372b9d', '842dc3f7-ab2d-4241-a2a1-fbbd3e36fdaa', $bp$God handed them over to him as a punishment after the fall of man$bp$, $bp$Dieu les lui a livrés en punition après la chute de l'homme$bp$, FALSE, 0),
      ('d4e47666-23db-4705-95c9-b3858c6a7425', '842dc3f7-ab2d-4241-a2a1-fbbd3e36fdaa', $bp$Man surrendered his authority, because dominion follows allegiance$bp$, $bp$L'homme a abandonné son autorité, car la domination suit l'allégeance$bp$, TRUE, 1),
      ('fab52c45-e38d-4a63-866d-f74e0599ceb7', '842dc3f7-ab2d-4241-a2a1-fbbd3e36fdaa', $bp$Adam sold them to him in exchange for knowledge and a wiser mind$bp$, $bp$Adam les lui a vendus en échange de connaissance et d'un esprit plus sage$bp$, FALSE, 2),
      ('2aea10ba-2534-4465-a9db-696b2e8d2f31', '842dc3f7-ab2d-4241-a2a1-fbbd3e36fdaa', $bp$He won them in a war in Heaven, and then took them from man by force$bp$, $bp$Il les a gagnés dans une guerre au Ciel, puis les a pris à l'homme par la force$bp$, FALSE, 3),
      ('b721c27c-6c7c-40ad-8e42-417517e3358e', '0aab5d4d-571b-499e-a972-714b81231b73', $bp$A theory invented by scholars, which helps explain how God rules over all creation$bp$, $bp$Une théorie inventée par des savants, qui aide à expliquer comment Dieu règne sur toute la création$bp$, FALSE, 0),
      ('126b3f55-a022-4344-82cd-6d9774e21467', '0aab5d4d-571b-499e-a972-714b81231b73', $bp$A deep feeling of peace, which believers experience when they pray and worship God$bp$, $bp$Un profond sentiment de paix, que les croyants éprouvent lorsqu'ils prient et adorent Dieu$bp$, FALSE, 1),
      ('53212931-aae4-4339-a818-82a79439f358', '0aab5d4d-571b-499e-a972-714b81231b73', $bp$A symbol of good behaviour, which describes how believers should live on the earth$bp$, $bp$Un symbole de bonne conduite, qui décrit comment les croyants doivent vivre sur la terre$bp$, FALSE, 2),
      ('37e484ae-610b-4b2a-a244-f6a76142f70b', '0aab5d4d-571b-499e-a972-714b81231b73', $bp$A real, living, inhabited realm, as real as the physical world and far more permanent$bp$, $bp$Un domaine réel, vivant et habité, aussi réel que le monde physique et bien plus durable$bp$, TRUE, 3),
      ('42faa33c-1e81-482e-8beb-8458bb8f4e13', 'dec89f49-5932-4e20-aeac-285e77c20d87', $bp$It is reserved for a spiritual elite who have trained for many years$bp$, $bp$Il est réservé à une élite spirituelle qui s'est formée pendant de nombreuses années$bp$, FALSE, 0),
      ('46694fb0-e7cd-44e0-872e-8aacb7cb3ed4', 'dec89f49-5932-4e20-aeac-285e77c20d87', $bp$It is mainly a religion, with rules and rituals that believers must follow$bp$, $bp$Il est surtout une religion, avec des règles et des rites que les croyants doivent suivre$bp$, FALSE, 1),
      ('6bdd73be-6293-477a-993e-056d908ec91e', 'dec89f49-5932-4e20-aeac-285e77c20d87', $bp$It is only a future place, which believers will enter after they die$bp$, $bp$Il est seulement un lieu futur, où les croyants entreront après leur mort$bp$, FALSE, 2),
      ('9d49426d-c296-4a89-9bcb-6de0a9f17098', 'dec89f49-5932-4e20-aeac-285e77c20d87', $bp$It is a present reality, available and accessible to every person right now$bp$, $bp$C'est une réalité présente, disponible et accessible à chaque personne dès maintenant$bp$, TRUE, 3),
      ('fbe9588d-1862-4fce-a26c-cc882fef1024', '1ed10c42-3caa-44bb-8084-1a5fbbc716a7', $bp$He was seated in silence, watching the stoning without stepping in to help$bp$, $bp$Il était assis en silence, regardant la lapidation sans intervenir pour aider$bp$, FALSE, 0),
      ('eef22180-4b08-4c7f-8fe6-f89c7db17ee0', '1ed10c42-3caa-44bb-8084-1a5fbbc716a7', $bp$He was absent, which showed that Stephen had to face the moment alone$bp$, $bp$Il était absent, ce qui montrait qu'Étienne devait affronter ce moment seul$bp$, FALSE, 1),
      ('59161800-1763-4a97-900d-6718d3039510', '1ed10c42-3caa-44bb-8084-1a5fbbc716a7', $bp$He was weeping, because of the pain and suffering of His servant Stephen$bp$, $bp$Il pleurait, à cause de la douleur et de la souffrance de son serviteur Étienne$bp$, FALSE, 2),
      ('4992113d-fcfb-47ba-9c4d-6414109084f5', '1ed10c42-3caa-44bb-8084-1a5fbbc716a7', $bp$He was standing, not seated, for a man giving his life for the gospel$bp$, $bp$Il était debout, et non assis, pour un homme qui donnait sa vie pour l'Évangile$bp$, TRUE, 3),
      ('77754ffe-aa24-431c-9617-841eef3c6df5', 'b6732624-5f21-4d39-8e4a-925385cb9363', $bp$It will be placed inside believers after death, when they enter Heaven$bp$, $bp$Il sera placé en l'intérieur des croyants après la mort, quand ils entreront au Ciel$bp$, FALSE, 0),
      ('1a41f32d-eb31-47eb-add5-69dde1f54e6b', 'b6732624-5f21-4d39-8e4a-925385cb9363', $bp$It lives in every born-again believer and goes wherever the believer goes$bp$, $bp$Il vit en chaque croyant né de nouveau et va partout où va le croyant$bp$, TRUE, 1),
      ('69700d69-7870-4710-a8c6-012d988dcdfd', 'b6732624-5f21-4d39-8e4a-925385cb9363', $bp$It is only a feeling inside a person, which comes during times of worship$bp$, $bp$C'est seulement un sentiment intérieur, qui vient pendant les moments d'adoration$bp$, FALSE, 2),
      ('9ca6fa00-948b-4181-9787-6a4dbd5202ec', 'b6732624-5f21-4d39-8e4a-925385cb9363', $bp$It is found in church buildings, where believers gather to meet with God$bp$, $bp$On le trouve dans les bâtiments d'église, où les croyants se rassemblent pour rencontrer Dieu$bp$, FALSE, 3),
      ('846ce3a3-d6b1-4c64-afc9-93e3981706cf', '8bd06284-47e6-4b47-8e26-36806c2d4ce5', $bp$The use of words in ministry, so that believers do no teaching or preaching at all$bp$, $bp$L'usage des paroles dans le ministère, de sorte que les croyants ne feraient ni enseignement ni prédication$bp$, FALSE, 0),
      ('86bf1ac8-70ed-4ba0-ad65-1506ad63f386', '8bd06284-47e6-4b47-8e26-36806c2d4ce5', $bp$Religion that replaces real Kingdom authority with performance and empty activity$bp$, $bp$La religion qui remplace la vraie autorité du Royaume par la représentation et l'activité vide$bp$, TRUE, 1),
      ('b1ec17a6-6c38-4ee9-b444-bf381d598ad3', '8bd06284-47e6-4b47-8e26-36806c2d4ce5', $bp$The place of prayer, since the Kingdom moves only by strength and by effort$bp$, $bp$La place de la prière, puisque le Royaume n'avance que par la force et par l'effort$bp$, FALSE, 2),
      ('9f8c75e0-cdcc-439a-8f38-43d8f562131e', '8bd06284-47e6-4b47-8e26-36806c2d4ce5', $bp$The value of Scripture, since power matters and the written Word does not$bp$, $bp$La valeur de l'Écriture, puisque la puissance compte et que la Parole écrite ne compte pas$bp$, FALSE, 3),
      ('0f0d61cf-a619-4bf0-98d2-8f0b32288d3b', '828a5fd4-1d29-4d8d-9099-099053913881', $bp$One person expressing the Kingdom brought transformation and great joy to a whole city$bp$, $bp$Une seule personne exprimant le Royaume a apporté la transformation et une grande joie à toute une ville$bp$, TRUE, 0),
      ('307674c3-75ab-4031-8adc-928487cc6e3e', '828a5fd4-1d29-4d8d-9099-099053913881', $bp$He preached to a few individuals, and each one slowly changed over many years$bp$, $bp$Il a prêché à quelques personnes, et chacune a lentement changé au fil de nombreuses années$bp$, FALSE, 1),
      ('71f5f0b6-60bf-48c8-8ecc-f6d7dcb2330c', '828a5fd4-1d29-4d8d-9099-099053913881', $bp$He was rejected by the city, and only a handful of people believed his message$bp$, $bp$Il a été rejeté par la ville, et seule une poignée de personnes ont cru à son message$bp$, FALSE, 2),
      ('4c7e6c73-6460-4eb5-8ecc-76eb6ab761da', '828a5fd4-1d29-4d8d-9099-099053913881', $bp$He built a large church that became the centre of influence over the region$bp$, $bp$Il a bâti une grande Église qui est devenue le centre d'influence de la région$bp$, FALSE, 3),
      ('2ac7317e-d15e-4263-99be-a079d358672e', 'a0ae2341-8ae4-4dd2-85f5-9ec0f47e33e0', $bp$So that its divine origin would be unmistakably clear to everyone who sees it$bp$, $bp$Pour que son origine divine soit clairement évidente pour tous ceux qui la voient$bp$, TRUE, 0),
      ('60bf5158-52b1-4ac2-ae22-d83ed2570351', 'a0ae2341-8ae4-4dd2-85f5-9ec0f47e33e0', $bp$Because ordinary people are the strongest vessels, able to carry it without failing$bp$, $bp$Parce que les gens ordinaires sont les vases les plus solides, capables de la porter sans faillir$bp$, FALSE, 1),
      ('c5bfa43e-9bd9-4c57-bff4-df7fe3a379fe', 'a0ae2341-8ae4-4dd2-85f5-9ec0f47e33e0', $bp$Because angels refused to carry the power, so God turned to human beings$bp$, $bp$Parce que les anges ont refusé de porter la puissance, alors Dieu s'est tourné vers les êtres humains$bp$, FALSE, 2),
      ('3b295127-1f03-4da4-935e-14ffe2f62521', 'a0ae2341-8ae4-4dd2-85f5-9ec0f47e33e0', $bp$So that the enemy would not find the power, since it was hidden in weakness$bp$, $bp$Pour que l'ennemi ne trouve pas la puissance, puisqu'elle était cachée dans la faiblesse$bp$, FALSE, 3),
      ('7f2dab0c-1c85-4fe6-9f8d-3ff73725c9fc', '543904c1-ea4a-4b1f-948c-11450b89edc4', $bp$A list of behaviours to avoid, so that the worthy could be separated from others$bp$, $bp$Une liste de comportements à éviter, pour séparer les gens dignes des autres$bp$, FALSE, 0),
      ('39e18730-0198-46d4-abb8-68be7f3b7309', '543904c1-ea4a-4b1f-948c-11450b89edc4', $bp$A religious system, with rituals that people had to follow to become clean$bp$, $bp$Un système religieux, avec des rites que les gens devaient suivre pour devenir purs$bp$, FALSE, 1),
      ('35d9c1d3-f969-4cdd-bd62-15bc5a3b68fa', '543904c1-ea4a-4b1f-948c-11450b89edc4', $bp$That the Kingdom of God is at hand, near, and available to everyone$bp$, $bp$Que le royaume de Dieu est proche, tout près et accessible à tous$bp$, TRUE, 2),
      ('6aed4d4e-6ad2-4c9a-921c-e1e1dfa2765b', '543904c1-ea4a-4b1f-948c-11450b89edc4', $bp$A moral code, with clear rules for how every believer should behave daily$bp$, $bp$Un code moral, avec des règles claires sur la façon dont chaque croyant doit se comporter chaque jour$bp$, FALSE, 3),
      ('3d90ad49-f705-4d02-81c5-c749ba948e85', '8abde7d6-15a7-49d5-aaf2-94f0f98a7d07', $bp$Man needed to prove himself worthy first, and only a long life of religious effort could do that$bp$, $bp$L'homme devait d'abord prouver sa valeur, et seule une longue vie d'efforts religieux pouvait le faire$bp$, FALSE, 0),
      ('d7e0b30b-8249-4165-9c31-e4abac2f8035', '8abde7d6-15a7-49d5-aaf2-94f0f98a7d07', $bp$God needed a payment for His many kindnesses, and only an animal sacrifice offered each year could do it$bp$, $bp$Dieu avait besoin d'un paiement pour ses nombreuses bontés, et seul un sacrifice animal offert chaque année pouvait le faire$bp$, FALSE, 1),
      ('8d15c6c7-4648-4e8c-ae5a-c77e15280c91', '8abde7d6-15a7-49d5-aaf2-94f0f98a7d07', $bp$The law demanded endless rituals, and only a priest from the tribe of Levi could finish them$bp$, $bp$La loi exigeait des rites sans fin, et seul un prêtre de la tribu de Lévi pouvait les achever$bp$, FALSE, 2),
      ('cf5c4df9-2d0e-452a-83b2-ca1272255ed3', '8abde7d6-15a7-49d5-aaf2-94f0f98a7d07', $bp$Sin brought a penalty that could not be ignored, and only Christ, fully God and fully man, could pay it$bp$, $bp$Le péché avait entraîné une peine qu'on ne pouvait ignorer, et seul Christ, pleinement Dieu et pleinement homme, pouvait la payer$bp$, TRUE, 3),
      ('775c5401-29b2-4d57-afd1-dd9b3fd8fd64', '87a79505-ea6a-40b5-8dcb-5b8491affc05', $bp$He was saved by water baptism, which he received from the soldiers shortly before he died$bp$, $bp$Il a été sauvé par le baptême d'eau, qu'il a reçu des soldats peu avant de mourir$bp$, FALSE, 0),
      ('5006898a-a1f8-41d9-a8d4-e7ac555c81f3', '87a79505-ea6a-40b5-8dcb-5b8491affc05', $bp$He had no time to prove himself, yet he turned to Jesus and was received, so no one is too far gone$bp$, $bp$Il n'a pas eu le temps de faire ses preuves, pourtant il s'est tourné vers Jésus et a été reçu : personne n'est trop loin$bp$, TRUE, 1),
      ('ee94f30f-0cc2-47a0-a56e-d0be9e1638a2', '87a79505-ea6a-40b5-8dcb-5b8491affc05', $bp$He could not be saved because he was too late, and his time to respond had already passed$bp$, $bp$Il ne pouvait pas être sauvé parce qu'il était trop tard, et son temps pour répondre était passé$bp$, FALSE, 2),
      ('8d699293-de7e-4c9b-b148-2a8529fd6446', '87a79505-ea6a-40b5-8dcb-5b8491affc05', $bp$He was saved because of his good life, which Jesus noticed in his final moments before death$bp$, $bp$Il a été sauvé à cause de sa bonne vie, que Jésus a remarquée dans ses derniers instants avant la mort$bp$, FALSE, 3),
      ('62c710a5-6a6b-4205-8bc1-e71f27b5cc83', '2d3e9405-8c2d-402c-a618-4fdd87450ac1', $bp$It is a gift, freely given and fully paid for, not a reward for good behaviour$bp$, $bp$C'est un don, offert gratuitement et entièrement payé, et non une récompense pour bonne conduite$bp$, TRUE, 0),
      ('b408ffac-8928-4069-81ea-4a15d9acf842', '2d3e9405-8c2d-402c-a618-4fdd87450ac1', $bp$It is only a partial restoration, and it will return in full only after death$bp$, $bp$Ce n'est qu'une restauration partielle, qui ne sera rendue en plénitude qu'après la mort$bp$, FALSE, 1),
      ('1bd0a6d3-f817-4a13-9cf1-b99d8b0a4d1a', '2d3e9405-8c2d-402c-a618-4fdd87450ac1', $bp$It is a prize, won by the most religious, who have kept the rules most faithfully$bp$, $bp$C'est un prix, remporté par les plus religieux, qui ont le plus fidèlement gardé les règles$bp$, FALSE, 2),
      ('3f9ca6ef-3fd5-4773-a6e0-9f112d5ecc05', '2d3e9405-8c2d-402c-a618-4fdd87450ac1', $bp$It is a position for leaders, who have been trained and sent out by the church$bp$, $bp$C'est une position pour les dirigeants, qui ont été formés et envoyés par l'Église$bp$, FALSE, 3),
      ('7271a05c-bfce-4732-bce6-ab1b328544f3', 'e92fa7b1-92d9-490c-87ee-fe2185586a0a', $bp$Timing does not matter to God, because His purposes never depend on the generation you live in$bp$, $bp$Le moment n'a pas d'importance pour Dieu, car ses desseins ne dépendent jamais de la génération dans laquelle vous vivez$bp$, FALSE, 0),
      ('df6b731e-4a63-46bb-8a54-bf378b71e251', 'e92fa7b1-92d9-490c-87ee-fe2185586a0a', $bp$You were placed in this generation by Heaven's design, not merely to survive it but to influence it$bp$, $bp$Vous avez été placé dans cette génération par le plan du Ciel, non seulement pour y survivre mais pour l'influencer$bp$, TRUE, 1),
      ('66930e4d-c5fd-4532-bdcf-3a06e85cd973', 'e92fa7b1-92d9-490c-87ee-fe2185586a0a', $bp$You should avoid risks, and wait until every danger has passed before you obey Him$bp$, $bp$Vous devriez éviter les risques et attendre que tout danger soit passé avant de lui obéir$bp$, FALSE, 2),
      ('800366df-a071-4081-9b46-eb795a3debb5', 'e92fa7b1-92d9-490c-87ee-fe2185586a0a', $bp$Only people in high positions, like queens and kings, receive such assignments from God$bp$, $bp$Seules les personnes occupant de hautes positions, comme les reines et les rois, reçoivent de telles missions de Dieu$bp$, FALSE, 3),
      ('09aafc89-d816-43ff-801a-202f716b9956', 'ffdf1271-093d-4b77-8f43-0ba92eecd04f', $bp$TRUE$bp$, $bp$VRAI$bp$, TRUE, 0),
      ('d2f28361-fc70-4775-90da-ee9612505941', 'ffdf1271-093d-4b77-8f43-0ba92eecd04f', $bp$FALSE$bp$, $bp$FAUX$bp$, FALSE, 1),
      ('e7c8e040-dbad-4259-b367-495a32c236eb', 'f068c0a4-e796-455a-be40-570faffedd9d', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('f3a4dd56-274c-42bc-8e59-7c70f18bd929', 'f068c0a4-e796-455a-be40-570faffedd9d', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1),
      ('ab8a758c-c0ad-4558-a390-294150a0fdd4', '6a2020ea-1b82-4b80-82aa-5f6086c108ef', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('b6b38e5e-b347-40cc-b51f-b180979252c8', '6a2020ea-1b82-4b80-82aa-5f6086c108ef', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1),
      ('1e1f143f-da72-4dad-8f9f-d8405e59e43c', '28357ddc-ad45-4413-8985-219edadf89a9', $bp$TRUE$bp$, $bp$VRAI$bp$, TRUE, 0),
      ('fd41deff-ad18-4a65-afad-fe8cf1a51f32', '28357ddc-ad45-4413-8985-219edadf89a9', $bp$FALSE$bp$, $bp$FAUX$bp$, FALSE, 1),
      ('86abadf0-5754-44a0-92da-c7f747a110bc', 'ecd2a80e-ad3f-49d0-bf20-f0b8979c4a61', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('2e4e787e-3cd7-4ef3-80bf-88677e476259', 'ecd2a80e-ad3f-49d0-bf20-f0b8979c4a61', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1);
    INSERT INTO "PersonalQuestion" ("id", "assessmentId", "setNumber", "order", "kind", "textEn", "textFr", "bodyEn", "bodyFr", "guideEn", "guideFr", "required", "flagUnlessNone", "affectsStatus") VALUES
      ('cfc82852-a1c0-4ad9-91c5-82ed2eb8514c', a_id, 2, 0, 'CHOICE', $bp$The book says receiving Christ and entering the Kingdom are the same thing. Would you say you have been translated out of the kingdom of darkness into the Kingdom of God's dear Son (Colossians 1:13)?$bp$, $bp$Le livre dit que recevoir Christ et entrer dans le Royaume sont la même chose. Diriez-vous que vous avez été transporté hors du royaume des ténèbres dans le royaume du Fils bien-aimé de Dieu (Colossiens 1.13) ?$bp$, NULL, NULL, $bp$Yes: affirm them. Uncertain, no, or do not know: explain that there is no second step; receiving Christ is receiving the Kingdom (Chapter Five). Offer to pray with them.$bp$, $bp$Oui : affirmez-la. Incertaine, non ou ne sait pas : expliquez qu'il n'y a pas de seconde étape ; recevoir Christ, c'est recevoir le Royaume (chapitre cinq). Proposez de prier avec elle.$bp$, TRUE, FALSE, TRUE),
      ('23a4132a-195d-464a-9a43-6a20490a67b1', a_id, 2, 1, 'TEXT', $bp$The book says no one is disqualified: Zacchaeus, the woman at the well, the thief on the cross, Cornelius, and Saul all received. Have you ever felt that your past disqualifies you? Which of these people do you relate to most, and why?$bp$, $bp$Le livre dit que personne n'est disqualifié : Zachée, la femme au puits, le voleur sur la croix, Corneille et Saul ont tous reçu. Avez-vous déjà senti que votre passé vous disqualifie ? Duquel de ces personnages vous sentez-vous le plus proche, et pourquoi ?$bp$, NULL, NULL, $bp$This shows the person's real fear. Answer it with the specific story they chose, and remind them that Saul of Tarsus was not disqualified.$bp$, $bp$Cela montre la vraie peur de la personne. Répondez-y avec l'histoire précise qu'elle a choisie, et rappelez-lui que Saul de Tarse n'était pas disqualifié.$bp$, TRUE, FALSE, TRUE),
      ('7679992b-7419-4a58-b890-688bf5322577', a_id, 2, 2, 'CHOICE', $bp$Have you prayed the prayer of salvation at the end of Chapter Five, or one like it, sincerely from your heart?$bp$, $bp$Avez-vous prié la prière du salut de la fin du chapitre cinq, ou une prière semblable, sincèrement du fond du cœur ?$bp$, NULL, NULL, $bp$Any answer except the first two: offer to pray the Chapter Five prayer together right now, or arrange a private conversation.$bp$, $bp$Toute réponse sauf les deux premières : proposez de prier ensemble tout de suite la prière du chapitre cinq, ou convenez d'un entretien privé.$bp$, TRUE, FALSE, TRUE),
      ('2bcf3622-1dfd-48eb-84cf-dba7ff041d1a', a_id, 2, 3, 'TEXT', $bp$The book says that if you pray it sincerely, old things have passed away and all things have become new. If you have prayed it, what has changed in how you see yourself?$bp$, $bp$Le livre dit que si vous la priez sincèrement, les choses anciennes sont passées et toutes choses sont devenues nouvelles. Si vous l'avez priée, qu'est-ce qui a changé dans la manière dont vous vous voyez ?$bp$, NULL, NULL, $bp$Look for real change (peace, freedom, new desire for the Word). If they wrote "not yet", treat it as an open door for a conversation.$bp$, $bp$Cherchez un vrai changement (paix, liberté, nouveau désir de la Parole). Si elle a écrit « pas encore », voyez-y une porte ouverte pour une conversation.$bp$, TRUE, FALSE, TRUE),
      ('0a336f59-7c60-4b12-afea-5cf459bb0a28', a_id, 2, 4, 'TEXT', $bp$The book warns of voices that say "this can wait", the same strategy used since Eden. Is any voice telling you to delay your decision? What is it saying?$bp$, $bp$Le livre met en garde contre les voix qui disent « cela peut attendre », la même stratégie utilisée depuis Éden. Une voix vous dit-elle de retarder votre décision ? Que dit-elle ?$bp$, NULL, NULL, $bp$Write down the voice they name and answer it from the book: "The Kingdom is at hand, not at some future point. Now."$bp$, $bp$Notez la voix qu'elle nomme et répondez-y à partir du livre : « Le royaume est proche, pas à un moment futur. Maintenant. »$bp$, TRUE, TRUE, TRUE),
      ('6976d18a-fad8-443e-a349-ed19ba8b6f95', a_id, 2, 5, 'CHOICE', $bp$My Confession of Faith$bp$, $bp$Ma confession de foi$bp$, $bp$Read this confession slowly, and think about every word. If it is the true desire of your heart, tick "I agree". If you are not ready, tick "I do not agree". You will not be judged for being honest.
    INSERT INTO "PersonalOption" ("id", "questionId", "order", "textEn", "textFr", "signal") VALUES
      ('e5bc111b-8545-43b8-a37a-b549c1abb384', 'cfc82852-a1c0-4ad9-91c5-82ed2eb8514c', 0, $bp$Yes, I am a citizen of the Kingdom$bp$, $bp$Oui, je suis citoyen du Royaume$bp$, 'POSITIVE'),
      ('59074efb-b919-4570-8e27-a55330608b3f', 'cfc82852-a1c0-4ad9-91c5-82ed2eb8514c', 1, $bp$I think so, but I am not certain$bp$, $bp$Je le pense, mais je n'en suis pas certain$bp$, 'NEEDS_TALK'),
      ('78d27fd1-0539-4af7-87d9-1e007f9231a6', 'cfc82852-a1c0-4ad9-91c5-82ed2eb8514c', 2, $bp$No, not yet$bp$, $bp$Non, pas encore$bp$, 'NEEDS_TALK'),
      ('3255aa2b-2ef2-4374-9b95-4dc83befb738', 'cfc82852-a1c0-4ad9-91c5-82ed2eb8514c', 3, $bp$I do not know$bp$, $bp$Je ne sais pas$bp$, 'NEEDS_TALK'),
      ('b3ec8633-1234-4c09-bcfb-91cb33299e27', '7679992b-7419-4a58-b890-688bf5322577', 0, $bp$Yes, while I was reading this book$bp$, $bp$Oui, pendant que je lisais ce livre$bp$, 'POSITIVE'),
      ('d930b8ed-5fe0-43b5-a85b-85bbf4648337', '7679992b-7419-4a58-b890-688bf5322577', 1, $bp$Yes, before I read this book$bp$, $bp$Oui, avant de lire ce livre$bp$, 'POSITIVE'),
      ('cb38cee3-1a39-4a57-ad26-242aa0f2a511', '7679992b-7419-4a58-b890-688bf5322577', 2, $bp$Not yet, but I would like to pray it now$bp$, $bp$Pas encore, mais j'aimerais la prier maintenant$bp$, 'NEEDS_TALK'),
      ('2f49e205-140d-4514-9074-b7a44d0b795c', '7679992b-7419-4a58-b890-688bf5322577', 3, $bp$I would like to speak with someone first$bp$, $bp$J'aimerais d'abord parler avec quelqu'un$bp$, 'NEEDS_TALK'),
      ('6c040acd-9791-4314-b699-5c5e952065c2', '6976d18a-fad8-443e-a349-ed19ba8b6f95', 0, $bp$I agree with this confession, and I make it my own$bp$, $bp$Je suis d'accord avec cette confession, et je la fais mienne$bp$, 'POSITIVE'),
      ('6d3560d5-66c7-4c8c-8e5d-53612fcf4281', '6976d18a-fad8-443e-a349-ed19ba8b6f95', 1, $bp$I do not agree with this confession$bp$, $bp$Je ne suis pas d'accord avec cette confession$bp$, 'NEEDS_TALK');
    INSERT INTO "Question" ("id", "assessmentId", "textEn", "textFr", "order", "points", "setNumber") VALUES
      ('5959e9a9-a596-423f-8317-bb3d069fffc6', a_id, $bp$Why does the Introduction say people turn to worry and stress when dominated by circumstances?$bp$, $bp$Pourquoi l'Introduction dit-elle que les gens se tournent vers l'inquiétude et le stress quand ils sont dominés par les circonstances ?$bp$, 0, 1, 3),
      ('b678f85c-8e48-4ea7-9722-f489adf02630', a_id, $bp$What does the Introduction say Jesus opened His ministry with?$bp$, $bp$Par quoi l'Introduction dit-elle que Jésus a ouvert son ministère ?$bp$, 1, 1, 3),
      ('f6bfc38d-193a-410e-9438-93302acc993d', a_id, $bp$What does the "king's image on a coin" illustration teach about man?$bp$, $bp$Que nous enseigne sur l'homme l'illustration de « l'image du roi sur une pièce de monnaie » ?$bp$, 2, 1, 3),
      ('64b2e5c1-2192-4b31-b21d-778017a7163a', a_id, $bp$What made man "the perfect bridge between Heaven and earth"?$bp$, $bp$Qu'est-ce qui a fait de l'homme « le pont parfait entre le Ciel et la terre » ?$bp$, 3, 1, 3),
      ('6b6563e9-f4d4-47b7-805b-6c46eb38e905', a_id, $bp$What does the book say Daniel's life teaches?$bp$, $bp$Qu'enseigne, selon le livre, la vie de Daniel ?$bp$, 4, 1, 3),
      ('135f0568-c60b-4d11-862e-bd64e95db3c8', a_id, $bp$Why does the book say the enemy needed to change man's beliefs?$bp$, $bp$Pourquoi le livre dit-il que l'ennemi avait besoin de changer les croyances de l'homme ?$bp$, 5, 1, 3),
      ('8bd1f325-30e0-4188-8e67-1f9c46cc667f', a_id, $bp$Which lie does the book say the enemy still whispers to every heart?$bp$, $bp$Quel mensonge le livre dit-il que l'ennemi murmure encore à chaque cœur ?$bp$, 6, 1, 3),
      ('4e61208c-f5b1-4f95-b36c-e2450c83ae4e', a_id, $bp$What does the book say Genesis 3:15 is?$bp$, $bp$Que dit le livre de Genèse 3.15 ?$bp$, 7, 1, 3),
      ('7350b5a0-4b32-4308-8552-1dd8096e8eb9', a_id, $bp$What does the book say about the government of the Kingdom of Heaven (Isaiah 9:6-7)?$bp$, $bp$Que dit le livre du gouvernement du Royaume des Cieux (Ésaïe 9.5-6) ?$bp$, 8, 1, 3),
      ('bf01d8f1-3ae2-49dc-8b04-7b61bfb384ca', a_id, $bp$According to the book, what is man's greatest need?$bp$, $bp$Selon le livre, quel est le plus grand besoin de l'homme ?$bp$, 9, 1, 3),
      ('8c1a293a-7e4d-42ab-a01e-014063baae04', a_id, $bp$Who does the book say is the King of the Kingdom of Heaven?$bp$, $bp$Qui le livre dit-il être le Roi du Royaume des Cieux ?$bp$, 10, 1, 3),
      ('1aae7a36-7a30-41f2-9be0-33b8642f63d9', a_id, $bp$Which is the book's definition of the Kingdom of God?$bp$, $bp$Quelle est la définition du Royaume de Dieu donnée par le livre ?$bp$, 11, 1, 3),
      ('00643583-840e-4ad4-aa20-e13b89b94d50', a_id, $bp$What does the book say about Israel's dominion?$bp$, $bp$Que dit le livre de la domination d'Israël ?$bp$, 12, 1, 3),
      ('3ad9bf51-cacf-4749-ac89-dc0f22812360', a_id, $bp$How does the book describe the Holy Spirit in relation to the Kingdom?$bp$, $bp$Comment le livre décrit-il le Saint-Esprit par rapport au Royaume ?$bp$, 13, 1, 3),
      ('cf4b75f1-bdf8-4b53-8cfc-a065b48844fe', a_id, $bp$What does the book say the parables of the mustard seed and the leaven show?$bp$, $bp$Que montrent, selon le livre, les paraboles du grain de sénevé et du levain ?$bp$, 14, 1, 3),
      ('1a618c74-6991-4c5a-9435-aa64d07e13bb', a_id, $bp$What does "at hand" mean, according to the book?$bp$, $bp$Que signifie « proche », selon le livre ?$bp$, 15, 1, 3),
      ('485a099a-d521-424f-959e-e376c21ddbc6', a_id, $bp$According to the book, what is being "born again"?$bp$, $bp$Selon le livre, qu'est-ce que « naître de nouveau » ?$bp$, 16, 1, 3),
      ('1d632278-720b-43f7-8f31-ab1e43d17f3c', a_id, $bp$What does the book say about the voices that say the decision can wait?$bp$, $bp$Que dit le livre des voix qui disent que la décision peut attendre ?$bp$, 17, 1, 3),
      ('a54f5a59-35ee-45a5-b90e-718cd2337414', a_id, $bp$What does the book say about the identity "chosen, royal, holy, peculiar"?$bp$, $bp$Que dit le livre de l'identité « élu, royal, saint, particulier » ?$bp$, 18, 1, 3),
      ('8d3b64e0-a452-4dfd-a5c7-478d083c4fb4', a_id, $bp$What does the Conclusion say your assignment is?$bp$, $bp$Selon la Conclusion, quelle est votre mission ?$bp$, 19, 1, 3),
      ('8a9b2d2a-63f6-481c-be80-ae432e305673', a_id, $bp$The book says man was told to be fruitful and multiply, and that the Kingdom was designed to grow and spread without limit.$bp$, $bp$Le livre dit qu'il a été dit à l'homme d'être fécond et de multiplier, et que le Royaume a été conçu pour grandir et se répandre sans limite.$bp$, 20, 1, 3),
      ('70a24a70-fd73-444f-9b82-d0a000f1ffff', a_id, $bp$The book says every person born after the fall entered the world spiritually disconnected from God.$bp$, $bp$Le livre dit que toute personne née après la chute est entrée dans le monde spirituellement séparée de Dieu.$bp$, 21, 1, 3),
      ('7ae111ab-b6af-494e-bcd5-dce6516b13cd', a_id, $bp$The book says there is no sickness, no lack, and no fear in Heaven.$bp$, $bp$Le livre dit qu'au Ciel il n'y a ni maladie, ni manque, ni peur.$bp$, 22, 1, 3),
      ('eb724af3-0c01-4396-ac7d-a6e658aaa8c4', a_id, $bp$The book says the Kingdom of God can be found in a particular building or place.$bp$, $bp$Le livre dit que le royaume de Dieu peut se trouver dans un bâtiment ou un lieu particulier.$bp$, 23, 1, 3),
      ('fe62b911-7730-4dc8-8971-55c46c8c8fad', a_id, $bp$The book says you must first clean up your life before you can enter the Kingdom.$bp$, $bp$Le livre dit qu'il faut d'abord nettoyer sa vie avant de pouvoir entrer dans le Royaume.$bp$, 24, 1, 3);
    INSERT INTO "Option" ("id", "questionId", "textEn", "textFr", "isCorrect", "order") VALUES
      ('486313c5-0e73-4106-972b-b6f5e326b0fc', '5959e9a9-a596-423f-8317-bb3d069fffc6', $bp$They were created to dictate over circumstances, so being dictated to is uncomfortable$bp$, $bp$Ils ont été créés pour dominer les circonstances, donc se faire dicter sa conduite est inconfortable$bp$, TRUE, 0),
      ('5bd7caa2-ed84-432b-bb15-12eeea6ab2de', '5959e9a9-a596-423f-8317-bb3d069fffc6', $bp$Stress is a normal part of being human, and every person on earth must learn to bear it$bp$, $bp$Le stress fait normalement partie de la condition humaine, et chaque personne sur terre doit apprendre à le supporter$bp$, FALSE, 1),
      ('89efd239-f25d-40ec-98d2-b9f1acad57ee', '5959e9a9-a596-423f-8317-bb3d069fffc6', $bp$They do not have enough money, and money would remove most of the pressure on them$bp$, $bp$Ils n'ont pas assez d'argent, et l'argent supprimerait la plus grande partie de la pression sur eux$bp$, FALSE, 2),
      ('8796ce55-c56d-429b-a352-c8902b4b8ead', '5959e9a9-a596-423f-8317-bb3d069fffc6', $bp$They have not studied enough, and more knowledge would remove most of the pressure$bp$, $bp$Ils n'ont pas assez étudié, et plus de connaissances supprimeraient la plus grande partie de la pression$bp$, FALSE, 3),
      ('d85c5cfc-1d4f-4b62-bd69-6294bec06872', 'b678f85c-8e48-4ea7-9722-f489adf02630', $bp$A series of miracles, which proved to the crowds that He was sent by God$bp$, $bp$Une série de miracles, qui prouvaient aux foules qu'il était envoyé par Dieu$bp$, FALSE, 0),
      ('16793891-9e2e-4827-98c7-9e9c6ede7a19', 'b678f85c-8e48-4ea7-9722-f489adf02630', $bp$A political manifesto, which promised to free the nation from the Roman rulers$bp$, $bp$Un manifeste politique, qui promettait de libérer la nation des dirigeants romains$bp$, FALSE, 1),
      ('6906eb4e-0562-4b93-918b-8946cc41e82b', 'b678f85c-8e48-4ea7-9722-f489adf02630', $bp$A bold declaration that the Kingdom of God was at hand and within reach$bp$, $bp$Une déclaration audacieuse que le royaume de Dieu était proche et à portée de main$bp$, TRUE, 2),
      ('fa010d1a-0c42-4055-9fba-07d40faa0efd', 'b678f85c-8e48-4ea7-9722-f489adf02630', $bp$A religious programme, which set out the rituals that people should follow$bp$, $bp$Un programme religieux, qui exposait les rites que les gens devaient suivre$bp$, FALSE, 3),
      ('7b93ae2a-a064-4866-87ed-20d39fc3918d', 'f6bfc38d-193a-410e-9438-93302acc993d', $bp$Man is valuable like money, and his worth depends on what others will pay$bp$, $bp$L'homme a de la valeur comme l'argent, et sa valeur dépend de ce que les autres sont prêts à payer$bp$, FALSE, 0),
      ('a837638b-f890-4250-b305-c4f90b68b775', 'f6bfc38d-193a-410e-9438-93302acc993d', $bp$Man has no choice in his actions, because the King stamps his every decision$bp$, $bp$L'homme n'a aucun choix dans ses actes, car le Roi marque chacune de ses décisions$bp$, FALSE, 1),
      ('bc43594c-133c-4dcb-b6ea-d10bd4ef17db', 'f6bfc38d-193a-410e-9438-93302acc993d', $bp$Man can be spent or traded, since God uses people as He uses coins$bp$, $bp$L'homme peut être dépensé ou échangé, puisque Dieu se sert des gens comme il se sert des pièces$bp$, FALSE, 2),
      ('c4dbef4b-d4b3-4da7-a74f-5b970e253567', 'f6bfc38d-193a-410e-9438-93302acc993d', $bp$Wherever man goes, he represents the authority and nature of the King$bp$, $bp$Partout où va l'homme, il représente l'autorité et la nature du Roi$bp$, TRUE, 3),
      ('71dffdff-6f4b-4d2e-9f10-e62c723ade1c', '64b2e5c1-2192-4b31-b21d-778017a7163a', $bp$He lives in two cities, one in Heaven and one on earth, and walks between them$bp$, $bp$Il vit dans deux cités, une au Ciel et une sur la terre, et marche de l'une à l'autre$bp$, FALSE, 0),
      ('a7c0de0b-bb80-4e6f-9e56-6592f1787f67', '64b2e5c1-2192-4b31-b21d-778017a7163a', $bp$He can travel between the spiritual and physical worlds whenever he chooses to$bp$, $bp$Il peut voyager entre le monde spirituel et le monde physique quand il le décide$bp$, FALSE, 1),
      ('9718311c-91e5-4916-b899-f4bec993f3b3', '64b2e5c1-2192-4b31-b21d-778017a7163a', $bp$He is a spirit being living in a physical body, so he can relate to both realms$bp$, $bp$Il est un être spirituel vivant dans un corps physique, donc il peut être en relation avec les deux domaines$bp$, TRUE, 2),
      ('89f4052b-1d53-4f0c-8022-ab8baafe2946', '64b2e5c1-2192-4b31-b21d-778017a7163a', $bp$He is half angel and half human, which gives him a place in both realms$bp$, $bp$Il est à moitié ange et à moitié humain, ce qui lui donne une place dans les deux domaines$bp$, FALSE, 3),
      ('a65b77e9-91af-48df-b412-82ec37a9d4f8', '6b6563e9-f4d4-47b7-805b-6c46eb38e905', $bp$Believers should avoid foreign and hostile nations, so that their faith is not tested$bp$, $bp$Les croyants doivent éviter les nations étrangères et hostiles, afin que leur foi ne soit pas mise à l'épreuve$bp$, FALSE, 0),
      ('0cc80b43-10f4-4f3b-9214-577c560bdfac', '6b6563e9-f4d4-47b7-805b-6c46eb38e905', $bp$God only works in favourable places, where leaders and people welcome His servants$bp$, $bp$Dieu n'agit que dans des lieux favorables, où les dirigeants et le peuple accueillent ses serviteurs$bp$, FALSE, 1),
      ('d9f5b067-e028-47d1-9997-c2b6a73945b5', '6b6563e9-f4d4-47b7-805b-6c46eb38e905', $bp$Wisdom comes only through education, so believers should always study to become great$bp$, $bp$La sagesse ne vient que par l'éducation, donc les croyants doivent toujours étudier pour devenir grands$bp$, FALSE, 2),
      ('d611331d-0644-42a9-bb7b-a61bc58d3d9f', '6b6563e9-f4d4-47b7-805b-6c46eb38e905', $bp$The Kingdom of God can operate in you even when everything around you is working against you$bp$, $bp$Le Royaume de Dieu peut agir en vous même quand tout autour de vous travaille contre vous$bp$, TRUE, 3),
      ('6f9bb30e-9013-4897-9193-009a41f54b5f', '135f0568-c60b-4d11-862e-bd64e95db3c8', $bp$To give man more freedom, so that he could stop depending on Heaven's rule$bp$, $bp$Pour donner plus de liberté à l'homme, afin qu'il cesse de dépendre du règne du Ciel$bp$, FALSE, 0),
      ('8bf7344e-f457-429b-a6de-c098acec1392', '135f0568-c60b-4d11-862e-bd64e95db3c8', $bp$To replace God-shaped beliefs with his own and turn man into a tool against God's intent$bp$, $bp$Pour remplacer les croyances façonnées par Dieu par les siennes et faire de l'homme un instrument contre le dessein de Dieu$bp$, TRUE, 1),
      ('352c4604-8202-43c2-a806-df16d749b57d', '135f0568-c60b-4d11-862e-bd64e95db3c8', $bp$To make man humble, so that he would no longer need the fellowship of God$bp$, $bp$Pour rendre l'homme humble, afin qu'il n'ait plus besoin de la communion avec Dieu$bp$, FALSE, 2),
      ('8f98b171-ab07-4d83-b245-2c315f5c63a6', '135f0568-c60b-4d11-862e-bd64e95db3c8', $bp$To help man grow in knowledge, so that he would become wiser than God intended$bp$, $bp$Pour aider l'homme à grandir en connaissance, afin qu'il devienne plus sage que Dieu ne l'avait voulu$bp$, FALSE, 3),
      ('9df581d8-75af-44ff-bddb-2b9842e1a5ca', '8bd1f325-30e0-4188-8e67-1f9c46cc667f', $bp$You do not need God to be great; you can be the god of your own life$bp$, $bp$Vous n'avez pas besoin de Dieu pour être grand ; vous pouvez être le dieu de votre propre vie$bp$, TRUE, 0),
      ('ac1293de-1408-4327-a3fd-271b5223f09c', '8bd1f325-30e0-4188-8e67-1f9c46cc667f', $bp$You are too small to matter, and God has no interest in a person like you$bp$, $bp$Vous êtes trop petit pour compter, et Dieu ne s'intéresse pas à une personne comme vous$bp$, FALSE, 1),
      ('90d1f469-81e0-4a43-b74f-45b75b156629', '8bd1f325-30e0-4188-8e67-1f9c46cc667f', $bp$You will never succeed, because the world is against every person who tries$bp$, $bp$Vous ne réussirez jamais, parce que le monde est contre chaque personne qui essaie$bp$, FALSE, 2),
      ('e72a9a54-ac16-47ca-a12c-4ec2ff83a25d', '8bd1f325-30e0-4188-8e67-1f9c46cc667f', $bp$God does not exist, so you are free to live as you wish without any rule$bp$, $bp$Dieu n'existe pas, donc vous êtes libre de vivre comme vous voulez sans aucune règle$bp$, FALSE, 3),
      ('bce7bf64-0e26-40c3-a0ad-aa8794f4765c', '4e61208c-f5b1-4f95-b36c-e2450c83ae4e', $bp$A curse placed on the serpent alone, which had no meaning for the human race$bp$, $bp$Une malédiction placée sur le serpent seul, sans signification pour la race humaine$bp$, FALSE, 0),
      ('c8a2d96d-0903-4e5b-ad8d-adfb98349bd9', '4e61208c-f5b1-4f95-b36c-e2450c83ae4e', $bp$The first announcement of the coming of Christ, and the seed of the gospel of the Kingdom$bp$, $bp$La première annonce de la venue de Christ, et la semence de l'Évangile du Royaume$bp$, TRUE, 1),
      ('73a7f4ca-077b-4cec-910c-1c130e114063', '4e61208c-f5b1-4f95-b36c-e2450c83ae4e', $bp$A description of the garden, and the order that God set up for the creatures$bp$, $bp$Une description du jardin, et de l'ordre que Dieu avait établi pour les créatures$bp$, FALSE, 2),
      ('a6473545-f208-441b-ade7-baecc64b08ba', '4e61208c-f5b1-4f95-b36c-e2450c83ae4e', $bp$A warning given to Eve, which explained the pain that would follow her sin$bp$, $bp$Un avertissement donné à Ève, qui expliquait la douleur qui suivrait son péché$bp$, FALSE, 3),
      ('44a5b72b-3334-4499-8ec8-65032f633c9d', '7350b5a0-4b32-4308-8552-1dd8096e8eb9', $bp$It is limited to the church, and does not reach into the nations of the earth$bp$, $bp$Il se limite à l'Église et n'atteint pas les nations de la terre$bp$, FALSE, 0),
      ('0647bee2-3ceb-4a57-bcbb-2ec740f2f9e0', '7350b5a0-4b32-4308-8552-1dd8096e8eb9', $bp$It rises and falls over time, like the kingdoms and governments of this world$bp$, $bp$Il monte et décline avec le temps, comme les royaumes et les gouvernements de ce monde$bp$, FALSE, 1),
      ('0fa51063-3957-432c-9118-163551f4f0e9', '7350b5a0-4b32-4308-8552-1dd8096e8eb9', $bp$It is always increasing and expanding, and it will never come to an end$bp$, $bp$Il s'accroît et s'étend toujours, et il n'aura jamais de fin$bp$, TRUE, 2),
      ('8b582ba5-1dd2-48bf-9d9f-c41f76fffe09', '7350b5a0-4b32-4308-8552-1dd8096e8eb9', $bp$It will end with this world, when the old order of things passes away for ever$bp$, $bp$Il finira avec ce monde, quand l'ancien ordre des choses passera pour toujours$bp$, FALSE, 3),
      ('72a0b343-009c-42de-82ff-1601d2846779', 'bf01d8f1-3ae2-49dc-8b04-7b61bfb384ca', $bp$Greater wealth, which would remove lack and give people power over their lives$bp$, $bp$Plus de richesse, qui supprimerait le manque et donnerait aux gens du pouvoir sur leur vie$bp$, FALSE, 0),
      ('ec30803c-2cad-4695-86aa-0b99284c1cdf', 'bf01d8f1-3ae2-49dc-8b04-7b61bfb384ca', $bp$The Kingdom of Heaven, which is accessed only through Jesus Christ$bp$, $bp$Le Royaume des Cieux, auquel on n'accède que par Jésus-Christ$bp$, TRUE, 1),
      ('5c99841c-deb3-43ef-b528-b80154516fb6', 'bf01d8f1-3ae2-49dc-8b04-7b61bfb384ca', $bp$Political power, which would remove oppression and give people control of nations$bp$, $bp$Le pouvoir politique, qui supprimerait l'oppression et donnerait aux gens le contrôle des nations$bp$, FALSE, 2),
      ('bfcafc9e-cfb4-4f59-bc32-3f08c49eb3ad', 'bf01d8f1-3ae2-49dc-8b04-7b61bfb384ca', $bp$A better education, which would remove ignorance and open the mind to wisdom$bp$, $bp$Une meilleure éducation, qui supprimerait l'ignorance et ouvrirait l'esprit à la sagesse$bp$, FALSE, 3),
      ('2a17e384-25cb-449e-a4b0-980cd3b76dad', '8c1a293a-7e4d-42ab-a01e-014063baae04', $bp$An angel appointed by God, who rules on His behalf over all of Heaven's hosts$bp$, $bp$Un ange nommé par Dieu, qui règne en son nom sur toutes les armées du Ciel$bp$, FALSE, 0),
      ('138bb4ff-0a56-46c8-bcc8-40e4b0d5a3e6', '8c1a293a-7e4d-42ab-a01e-014063baae04', $bp$A council of elders, who govern the Kingdom together by agreement and wisdom$bp$, $bp$Un conseil d'anciens, qui gouvernent ensemble le Royaume par accord et sagesse$bp$, FALSE, 1),
      ('e1d57253-38b5-4df7-a2b8-cb14eafb3652', '8c1a293a-7e4d-42ab-a01e-014063baae04', $bp$Moses, the lawgiver, who first received the law of the Kingdom from God on the mountain$bp$, $bp$Moïse, le législateur, qui a le premier reçu de Dieu la loi du Royaume sur la montagne$bp$, FALSE, 2),
      ('63eae8a5-1429-463a-bd0c-296b3e2557f0', '8c1a293a-7e4d-42ab-a01e-014063baae04', $bp$Jesus, the Word made flesh, who holds all power in Heaven and earth$bp$, $bp$Jésus, la Parole faite chair, qui détient tout pouvoir dans le ciel et sur la terre$bp$, TRUE, 3),
      ('4895f440-4646-4986-be2f-10d44b390f59', '1aae7a36-7a30-41f2-9be0-33b8642f63d9', $bp$A future paradise that believers will enter after death, where all the effects of the fall will at last be removed$bp$, $bp$Un paradis futur où les croyants entreront après la mort, où tous les effets de la chute seront enfin supprimés$bp$, FALSE, 0),
      ('707abdec-db3f-470c-80b5-05581313c646', '1aae7a36-7a30-41f2-9be0-33b8642f63d9', $bp$A building or place on earth where believers gather, and where the presence of God is found more than anywhere else$bp$, $bp$Un bâtiment ou un lieu sur la terre où les croyants se rassemblent, et où la présence de Dieu se trouve plus qu'ailleurs$bp$, FALSE, 1),
      ('2e2f2039-920b-4f96-a87d-094d1e985206', '1aae7a36-7a30-41f2-9be0-33b8642f63d9', $bp$A set of rules and traditions for the church, kept by believers and enforced by its leaders in every local congregation$bp$, $bp$Un ensemble de règles et de traditions pour l'Église, observées par les croyants et imposées par ses dirigeants dans chaque assemblée locale$bp$, FALSE, 2),
      ('afcc6e26-85ab-49f1-9927-ac6e75917ccf', '1aae7a36-7a30-41f2-9be0-33b8642f63d9', $bp$The active, visible manifestation of Heaven's authority on earth, expressed through its citizens and shown by the power of the Holy Spirit$bp$, $bp$La manifestation active et visible de l'autorité du Ciel sur la terre, exprimée par ses citoyens et montrée par la puissance du Saint-Esprit$bp$, TRUE, 3),
      ('81587d63-02cc-485c-a132-4d33ae586a0d', '00643583-840e-4ad4-aa20-e13b89b94d50', $bp$Dominion was independent of obedience, since Israel was chosen and no failure could affect it$bp$, $bp$La domination était indépendante de l'obéissance, puisqu'Israël était choisi et qu'aucun échec ne pouvait l'affecter$bp$, FALSE, 0),
      ('00c3f023-69f3-4646-b120-023d34f18cf3', '00643583-840e-4ad4-aa20-e13b89b94d50', $bp$Dominion depended on Israel's size and military strength compared with the nations around them$bp$, $bp$La domination dépendait de la taille et de la force militaire d'Israël comparées aux nations voisines$bp$, FALSE, 1),
      ('b109d400-c6ea-4a0e-858a-1c01b63a434c', '00643583-840e-4ad4-aa20-e13b89b94d50', $bp$When connected to God, dominion was maintained; when connection was lost, dominion was lost$bp$, $bp$Quand il était relié à Dieu, la domination était maintenue ; quand le lien était perdu, la domination était perdue$bp$, TRUE, 2),
      ('52cbad19-691a-4eca-a3d8-8ab00cbe2500', '00643583-840e-4ad4-aa20-e13b89b94d50', $bp$Dominion never changed, because God's promise to Israel could never be taken away from them$bp$, $bp$La domination n'a jamais changé, car la promesse de Dieu à Israël ne pouvait jamais lui être retirée$bp$, FALSE, 3),
      ('145198d6-0659-447a-a3fa-8a4b9ec6eac5', '3ad9bf51-cacf-4749-ac89-dc0f22812360', $bp$A feeling that rises during worship, and then fades away when the music stops$bp$, $bp$Un sentiment qui monte pendant l'adoration, puis s'éteint quand la musique s'arrête$bp$, FALSE, 0),
      ('5363eea4-8070-43a1-a030-1288c601c272', '3ad9bf51-cacf-4749-ac89-dc0f22812360', $bp$A force that comes and goes, depending on how well the believer behaves each day$bp$, $bp$Une force qui va et vient, selon la manière dont le croyant se comporte chaque jour$bp$, FALSE, 1),
      ('5a76187a-e2ba-4348-ae86-c1c1309f5965', '3ad9bf51-cacf-4749-ac89-dc0f22812360', $bp$The personal presence of the Kingdom of God, living inside the believer$bp$, $bp$La présence personnelle du Royaume de Dieu, qui vit à l'intérieur du croyant$bp$, TRUE, 2),
      ('f1d8ced4-11b4-40c7-96fa-00d1f288f335', '3ad9bf51-cacf-4749-ac89-dc0f22812360', $bp$A gift reserved for pastors and leaders, who are set apart for ministry in the church$bp$, $bp$Un don réservé aux pasteurs et aux dirigeants, mis à part pour le ministère dans l'Église$bp$, FALSE, 3),
      ('dd2c02f0-e7ec-43d8-b5c4-6226fa7ee1e8', 'cf4b75f1-bdf8-4b53-8cfc-a065b48844fe', $bp$The Kingdom grows only inside the church, and does not reach into the culture$bp$, $bp$Le Royaume ne grandit qu'à l'intérieur de l'Église et n'atteint pas la culture$bp$, FALSE, 0),
      ('0d6ae0ec-d5f8-47d9-9378-467f0f955d38', 'cf4b75f1-bdf8-4b53-8cfc-a065b48844fe', $bp$The Kingdom starts small but grows and influences everything around it$bp$, $bp$Le Royaume commence petit mais grandit et influence tout ce qui l'entoure$bp$, TRUE, 1),
      ('3a3af1e9-3e5f-4e33-b0c5-f63b14d8741c', 'cf4b75f1-bdf8-4b53-8cfc-a065b48844fe', $bp$The Kingdom is meant for the rich, whose resources make it grow into a large tree$bp$, $bp$Le Royaume est destiné aux riches, dont les ressources le font grandir en un grand arbre$bp$, FALSE, 2),
      ('8b48ce99-e736-4db9-977a-6372b970cc44', 'cf4b75f1-bdf8-4b53-8cfc-a065b48844fe', $bp$The Kingdom stays hidden and small, and is never seen by the world around it$bp$, $bp$Le Royaume reste caché et petit, et n'est jamais vu du monde qui l'entoure$bp$, FALSE, 3),
      ('a626fcc1-f8a5-49ec-8f36-21734358b936', '1a618c74-6991-4c5a-9435-aa64d07e13bb', $bp$Close by, within reach, and available right now, not at some later time$bp$, $bp$Tout près, à portée de main et disponible maintenant, et non à un moment ultérieur$bp$, TRUE, 0),
      ('2adbb7ef-1861-431a-a667-8653ecb14299', '1a618c74-6991-4c5a-9435-aa64d07e13bb', $bp$Coming soon, after people have done much work to make themselves ready for it$bp$, $bp$Bientôt, après que les gens auront beaucoup travaillé pour s'y préparer$bp$, FALSE, 1),
      ('22b17c82-7b12-4437-ae53-688e74436c2b', '1a618c74-6991-4c5a-9435-aa64d07e13bb', $bp$Reserved for the end of the age, when Christ returns to rule over the earth$bp$, $bp$Réservé à la fin des temps, quand Christ reviendra régner sur la terre$bp$, FALSE, 2),
      ('0aec9584-4b09-436b-8483-b39d44f8b5a0', '1a618c74-6991-4c5a-9435-aa64d07e13bb', $bp$Far away, hard to reach, and available only to those who search for many years$bp$, $bp$Loin, difficile à atteindre et accessible seulement à ceux qui cherchent pendant de nombreuses années$bp$, FALSE, 3),
      ('5b4b8b5a-bd29-43ac-91b2-130016c9f747', '485a099a-d521-424f-959e-e376c21ddbc6', $bp$A religious ritual performed by a minister on your behalf, which joins you to a church and its members$bp$, $bp$Un rite religieux accompli à votre place par un ministre, qui vous rattache à une Église et à ses membres$bp$, FALSE, 0),
      ('f73293de-d37b-4147-98d8-830bd5ae8cfd', '485a099a-d521-424f-959e-e376c21ddbc6', $bp$Turning over a new leaf, in which a person resolves to leave bad habits and to do good$bp$, $bp$Tourner la page, quand une personne décide de quitter ses mauvaises habitudes et de faire le bien$bp$, FALSE, 1),
      ('c9b5b4a6-936b-4455-8ec5-52599a9fd797', '485a099a-d521-424f-959e-e376c21ddbc6', $bp$Joining a new church, in which a person takes on new beliefs and a new community$bp$, $bp$Rejoindre une nouvelle Église, quand une personne adopte de nouvelles croyances et une nouvelle communauté$bp$, FALSE, 2),
      ('7c4aba10-fffb-4fc3-a01e-41afd3252496', '485a099a-d521-424f-959e-e376c21ddbc6', $bp$A spiritual birth in which your dead spirit is made alive and reconnected to God through the Word$bp$, $bp$Une naissance spirituelle où votre esprit mort est rendu vivant et relié à Dieu par la Parole$bp$, TRUE, 3),
      ('37836d1e-8a83-45e9-9c38-4f8c1ef63c51', '1d632278-720b-43f7-8f31-ab1e43d17f3c', $bp$It is the voice of God, who is patient and tells people to wait for the right time$bp$, $bp$C'est la voix de Dieu, qui est patient et dit aux gens d'attendre le bon moment$bp$, FALSE, 0),
      ('ef2bdde2-5f9f-4a2f-9cec-0e131956790b', '1d632278-720b-43f7-8f31-ab1e43d17f3c', $bp$It is harmless, because a person who waits can always come to the Kingdom later$bp$, $bp$C'est sans danger, car une personne qui attend peut toujours venir au Royaume plus tard$bp$, FALSE, 1),
      ('878b2d4f-bae9-4884-9616-94eaf6bcb497', '1d632278-720b-43f7-8f31-ab1e43d17f3c', $bp$It is the same enemy strategy used since the Garden of Eden to keep people from their inheritance$bp$, $bp$C'est la même stratégie de l'ennemi utilisée depuis le jardin d'Éden pour éloigner les gens de leur héritage$bp$, TRUE, 2),
      ('5f2ddc54-40c4-4708-905f-6df6383a56b2', '1d632278-720b-43f7-8f31-ab1e43d17f3c', $bp$It is the voice of wisdom, which tells a person to think carefully before deciding$bp$, $bp$C'est la voix de la sagesse, qui dit à une personne de bien réfléchir avant de décider$bp$, FALSE, 3),
      ('e5974a13-748b-4677-a721-d78723132f6e', 'a54f5a59-35ee-45a5-b90e-718cd2337414', $bp$It is actual, not aspirational: it was given to you the moment you were born again$bp$, $bp$Elle est réelle, et non un idéal : elle vous a été donnée au moment où vous êtes né de nouveau$bp$, TRUE, 0),
      ('d1011874-cc0a-489f-b1a8-9b8c6aa3695f', 'a54f5a59-35ee-45a5-b90e-718cd2337414', $bp$It is only for ministers, who have been called and set apart for the work of God$bp$, $bp$Elle est seulement pour les ministres, qui ont été appelés et mis à part pour l'œuvre de Dieu$bp$, FALSE, 1),
      ('1e1428fa-cd91-40cc-aab5-54717ba566b1', 'a54f5a59-35ee-45a5-b90e-718cd2337414', $bp$It is a symbol, not a fact, which describes how believers ought to behave$bp$, $bp$C'est un symbole, non un fait, qui décrit comment les croyants devraient se comporter$bp$, FALSE, 2),
      ('4707efc2-28cd-4f65-a063-18903d5b91f7', 'a54f5a59-35ee-45a5-b90e-718cd2337414', $bp$It is a goal to reach, which believers grow into after decades of spiritual effort$bp$, $bp$C'est un but à atteindre, dans lequel les croyants grandissent après des décennies d'efforts spirituels$bp$, FALSE, 3),
      ('0815a509-db30-4ab2-ac82-0fa2121f3c5e', '8d3b64e0-a452-4dfd-a5c7-478d083c4fb4', $bp$To wait for a platform or a position in ministry, since only then will God use you to reach the nations and cities of the world$bp$, $bp$Attendre une plateforme ou une position dans le ministère, car c'est seulement alors que Dieu vous utilisera pour atteindre les nations et les villes du monde$bp$, FALSE, 0),
      ('d82946d9-470c-4562-acca-257d1a0febd8', '8d3b64e0-a452-4dfd-a5c7-478d083c4fb4', $bp$To carry the gospel of the Kingdom into your home, work, and community, because wherever you are planted is Kingdom territory$bp$, $bp$Porter l'Évangile du Royaume dans votre foyer, votre travail et votre communauté, car là où vous êtes planté est un territoire du Royaume$bp$, TRUE, 1),
      ('8be6cf3f-d8da-4011-8614-6127ca834a35', '8d3b64e0-a452-4dfd-a5c7-478d083c4fb4', $bp$To leave your job and your family, because the Kingdom requires a full break from the ordinary life of the world around you$bp$, $bp$Quitter votre emploi et votre famille, car le Royaume exige une rupture complète avec la vie ordinaire du monde qui vous entoure$bp$, FALSE, 2),
      ('e2b015c6-87c8-4065-b711-ef0f4d7093eb', '8d3b64e0-a452-4dfd-a5c7-478d083c4fb4', $bp$To avoid the world and its influence, because the Kingdom grows only among believers who stay completely apart from everyone else$bp$, $bp$Éviter le monde et son influence, car le Royaume ne grandit que parmi les croyants qui restent complètement à l'écart de tous les autres$bp$, FALSE, 3),
      ('77dce46b-10bb-4dfe-9311-58b981889219', '8a9b2d2a-63f6-481c-be80-ae432e305673', $bp$TRUE$bp$, $bp$VRAI$bp$, TRUE, 0),
      ('d3d6fa91-fc82-43c5-bb8c-44a03091f2f9', '8a9b2d2a-63f6-481c-be80-ae432e305673', $bp$FALSE$bp$, $bp$FAUX$bp$, FALSE, 1),
      ('ba7fcdac-b9d7-45c5-9e6b-65a803eb1d92', '70a24a70-fd73-444f-9b82-d0a000f1ffff', $bp$TRUE$bp$, $bp$VRAI$bp$, TRUE, 0),
      ('17563a95-49ef-4998-87b6-44675ae3e14e', '70a24a70-fd73-444f-9b82-d0a000f1ffff', $bp$FALSE$bp$, $bp$FAUX$bp$, FALSE, 1),
      ('bf9e38f8-7f2c-4706-ae51-54f3f854da09', '7ae111ab-b6af-494e-bcd5-dce6516b13cd', $bp$TRUE$bp$, $bp$VRAI$bp$, TRUE, 0),
      ('13df8f6c-c9c8-418f-9f31-70556455e7ed', '7ae111ab-b6af-494e-bcd5-dce6516b13cd', $bp$FALSE$bp$, $bp$FAUX$bp$, FALSE, 1),
      ('a11ece29-36b7-455f-bd88-48302b7dc216', 'eb724af3-0c01-4396-ac7d-a6e658aaa8c4', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('3c7b4222-dff3-4be6-90be-5b7d4ea312d8', 'eb724af3-0c01-4396-ac7d-a6e658aaa8c4', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1),
      ('edfe883e-13c4-48e6-b092-410c114ecf50', 'fe62b911-7730-4dc8-8971-55c46c8c8fad', $bp$TRUE$bp$, $bp$VRAI$bp$, FALSE, 0),
      ('e799189c-f31c-4e15-bca6-b5f86a5c504b', 'fe62b911-7730-4dc8-8971-55c46c8c8fad', $bp$FALSE$bp$, $bp$FAUX$bp$, TRUE, 1);
    INSERT INTO "PersonalQuestion" ("id", "assessmentId", "setNumber", "order", "kind", "textEn", "textFr", "bodyEn", "bodyFr", "guideEn", "guideFr", "required", "flagUnlessNone", "affectsStatus") VALUES
      ('40b8fbc0-a12c-4955-8771-990e60bb8d3e', a_id, 3, 0, 'CHOICE', $bp$Since the fall, every person is born spiritually disconnected from God. Do you sense that your connection with God has been restored through Jesus Christ?$bp$, $bp$Depuis la chute, chaque personne naît spirituellement séparée de Dieu. Sentez-vous que votre lien avec Dieu a été rétabli par Jésus-Christ ?$bp$, NULL, NULL, $bp$No or unsure: this is the heart of the book. Gently explain the new birth and pray the Chapter Five prayer with them. A yes with a clear story is a strong sign.$bp$, $bp$Non ou incertain : c'est le cœur du livre. Expliquez doucement la nouvelle naissance et priez avec elle la prière du chapitre cinq. Un oui accompagné d'une histoire claire est un signe fort.$bp$, TRUE, FALSE, TRUE),
      ('c5efbff0-7014-493c-99d3-e3635f345435', a_id, 3, 1, 'TEXT', $bp$If yes, how did you come to know it?$bp$, $bp$Si oui, comment l'avez-vous su ?$bp$, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE),
      ('8bdc091e-01e0-4c4a-894d-0bd722f24915', a_id, 3, 2, 'CHOICE', $bp$The prayer in Chapter Five asks God to fill you with His Holy Spirit. Have you asked God for this?$bp$, $bp$La prière du chapitre cinq demande à Dieu de vous remplir de son Saint-Esprit. L'avez-vous demandé à Dieu ?$bp$, NULL, NULL, $bp$Not yet or not sure: explain that believers receive the Holy Spirit by faith (Chapter Five prayer; Acts 1:8; Luke 11:13) and pray with them.$bp$, $bp$Pas encore ou pas sûr : expliquez que les croyants reçoivent le Saint-Esprit par la foi (prière du chapitre cinq ; Actes 1.8 ; Luc 11.13) et priez avec elle.$bp$, TRUE, FALSE, TRUE),
      ('be6742a6-219a-4610-ac96-a64b37270c00', a_id, 3, 3, 'CHOICE', $bp$The book says a newborn needs milk: the Word that birthed you must now grow you (1 Peter 2:2). What are you doing to grow in the Word?$bp$, $bp$Le livre dit qu'un nouveau-né a besoin de lait : la Parole qui vous a fait naître doit maintenant vous faire grandir (1 Pierre 2.2). Que faites-vous pour grandir dans la Parole ?$bp$, NULL, NULL, $bp$Anything but the first answer: help them start with a simple daily plan, such as a short reading and one verse each morning.$bp$, $bp$Toute réponse autre que la première : aidez-la à commencer par un plan quotidien simple, par exemple une courte lecture et un verset chaque matin.$bp$, TRUE, FALSE, FALSE),
      ('7504de86-4cdd-483f-9574-f513a309082f', a_id, 3, 4, 'CHOICE', $bp$The Conclusion asks: "Will you make yourself available?" Are you willing to be a Kingdom ambassador in your home, workplace, and community?$bp$, $bp$La Conclusion demande : « Vous rendrez-vous disponible ? » Êtes-vous prêt à être un ambassadeur du Royaume dans votre foyer, votre lieu de travail et votre communauté ?$bp$, NULL, NULL, $bp$"Willing, but need training" is the best invitation for leadership studies in the Academy. Note these people for follow-up.$bp$, $bp$« Prêt, mais besoin de formation » est la meilleure invitation aux études de leadership à l'Académie. Notez ces personnes pour un suivi.$bp$, TRUE, FALSE, FALSE),
      ('3b43c599-7ae8-43c2-be4e-b6a55dc92fbd', a_id, 3, 5, 'TEXT', $bp$In one or two sentences, write the decision you have made after reading this book.$bp$, $bp$En une ou deux phrases, écrivez la décision que vous avez prise après avoir lu ce livre.$bp$, NULL, NULL, $bp$Read it as their own testimony of response. Encourage any real decision, and contact anyone who wrote that they are undecided.$bp$, $bp$Lisez-la comme son propre témoignage de réponse. Encouragez toute décision réelle, et contactez toute personne qui a écrit qu'elle est indécise.$bp$, TRUE, FALSE, FALSE),
      ('1bda3f47-4845-406a-bf66-4d9e756097fc', a_id, 3, 6, 'CHOICE', $bp$My Confession of Faith$bp$, $bp$Ma confession de foi$bp$, $bp$Read this confession slowly, and think about every word. If it is the true desire of your heart, tick "I agree". If you are not ready, tick "I do not agree". You will not be judged for being honest.
    INSERT INTO "PersonalOption" ("id", "questionId", "order", "textEn", "textFr", "signal") VALUES
      ('386eeb43-68d5-4384-a42e-b7415d7b0224', '40b8fbc0-a12c-4955-8771-990e60bb8d3e', 0, $bp$Yes, I know I am reconnected to God$bp$, $bp$Oui, je sais que je suis relié à Dieu$bp$, 'POSITIVE'),
      ('290b2aff-fbef-46af-94f6-3416d34b34ae', '40b8fbc0-a12c-4955-8771-990e60bb8d3e', 1, $bp$I sense it sometimes, but I am not sure$bp$, $bp$Je le sens parfois, mais je n'en suis pas sûr$bp$, 'NEEDS_TALK'),
      ('2d18ebe2-de76-40a2-89e6-d6ef562b7004', '40b8fbc0-a12c-4955-8771-990e60bb8d3e', 2, $bp$No, I still feel disconnected$bp$, $bp$Non, je me sens encore séparé$bp$, 'NEEDS_TALK'),
      ('33d240f4-fce0-4582-a6e2-0a12d4df659f', '40b8fbc0-a12c-4955-8771-990e60bb8d3e', 3, $bp$I do not understand this$bp$, $bp$Je ne comprends pas cela$bp$, 'NEEDS_TALK'),
      ('5c56b7b8-b063-4682-aaba-e2ea1d8009ca', '8bdc091e-01e0-4c4a-894d-0bd722f24915', 0, $bp$Yes, and I have received Him by faith$bp$, $bp$Oui, et je l'ai reçu par la foi$bp$, 'POSITIVE'),
      ('d65d90ea-336f-478e-a486-1ac6790e81dc', '8bdc091e-01e0-4c4a-894d-0bd722f24915', 1, $bp$Yes, but I am not sure that I received$bp$, $bp$Oui, mais je ne suis pas sûr de l'avoir reçu$bp$, 'NEEDS_TALK'),
      ('16fd8d05-e3cd-4839-a374-0127cf04d383', '8bdc091e-01e0-4c4a-894d-0bd722f24915', 2, $bp$Not yet, but I would like to ask now$bp$, $bp$Pas encore, mais j'aimerais le demander maintenant$bp$, 'NEEDS_TALK'),
      ('9d8f5f8c-d185-4c8c-ba1b-4a9d85a5fec5', '8bdc091e-01e0-4c4a-894d-0bd722f24915', 3, $bp$I need someone to explain this to me$bp$, $bp$J'ai besoin que quelqu'un m'explique cela$bp$, 'NEEDS_TALK'),
      ('828bb5ee-a594-42ed-8a8a-39cbcd026e64', 'be6742a6-219a-4610-ac96-a64b37270c00', 0, $bp$I read and study the Word every day$bp$, $bp$Je lis et j'étudie la Parole chaque jour$bp$, 'POSITIVE'),
      ('cc15cee1-e923-412d-9e7b-76ce33628101', 'be6742a6-219a-4610-ac96-a64b37270c00', 1, $bp$I read it sometimes, but not regularly$bp$, $bp$Je la lis parfois, mais pas régulièrement$bp$, 'NEEDS_TALK'),
      ('d9ae2dfc-3aa1-47ed-a90e-8d41dd66c68a', 'be6742a6-219a-4610-ac96-a64b37270c00', 2, $bp$I am not reading it yet$bp$, $bp$Je ne la lis pas encore$bp$, 'NEEDS_TALK'),
      ('8be6d690-acbd-4c4b-9d36-35c10dfc0ff6', 'be6742a6-219a-4610-ac96-a64b37270c00', 3, $bp$I need help to begin$bp$, $bp$J'ai besoin d'aide pour commencer$bp$, 'NEEDS_TALK'),
      ('84827e37-b022-4c0b-aae5-96ec7ec51cfc', '7504de86-4cdd-483f-9574-f513a309082f', 0, $bp$Yes, I am available, and I am ready to serve$bp$, $bp$Oui, je suis disponible et prêt à servir$bp$, 'POSITIVE'),
      ('f6709c08-7601-48bb-abb5-2182bddea006', '7504de86-4cdd-483f-9574-f513a309082f', 1, $bp$I am willing, but I need training$bp$, $bp$Je suis prêt, mais j'ai besoin de formation$bp$, 'NEEDS_TALK'),
      ('c7cdad6f-a5a7-4f0a-8f8d-4a125401246f', '7504de86-4cdd-483f-9574-f513a309082f', 2, $bp$I am not ready yet$bp$, $bp$Je ne suis pas encore prêt$bp$, 'NEEDS_TALK'),
      ('4f1c6f2b-8b92-4958-8f6c-e93ba41a0d98', '7504de86-4cdd-483f-9574-f513a309082f', 3, $bp$I am not sure$bp$, $bp$Je ne suis pas sûr$bp$, 'NEEDS_TALK'),
      ('d7aeebf9-8c45-480d-9fc1-7ab5ba87a8be', '1bda3f47-4845-406a-bf66-4d9e756097fc', 0, $bp$I agree with this confession, and I make it my own$bp$, $bp$Je suis d'accord avec cette confession, et je la fais mienne$bp$, 'POSITIVE'),
      ('6572c3ad-d2e3-46e3-9f04-9cceb26d99fc', '1bda3f47-4845-406a-bf66-4d9e756097fc', 1, $bp$I do not agree with this confession$bp$, $bp$Je ne suis pas d'accord avec cette confession$bp$, 'NEEDS_TALK');
